+                .Where(u => u.NsapUserId != null)
+                .GroupBy(u => u.NsapUserId)
+                .ToDictionary(g => g.Key, g => g.First().UserID);
+
+            foreach (var item in result)
+            {
+                item.Erp3UserId = (int)(erpDict.TryGetValue(item.SlpCode, out var erpId) ? erpId : 0);
+                item.CustomerErp3UserId = (int)(item.CustomerSlpCode != null && erpDict.TryGetValue(item.CustomerSlpCode, out var cErpId) ? cErpId : 0);
+
+                item.SaleManId = item.Erp3UserId != null && userDict.TryGetValue(item.Erp3UserId, out var saleId) ? saleId : null;
