+        /// <summary>
+        /// 判断是否有除page和limit之外的搜索条件
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static bool HasOtherSearchFilters(ReceiptLoadReq req)
+        {
+            return !string.IsNullOrEmpty(req.Indicator)
+                || (req.IndicatorList != null && req.IndicatorList.Any())
+                || req.ReceiptDocEntry.HasValue
+                || req.SaleDocEntry.HasValue
+                || (req.SaleDocEntryList != null && req.SaleDocEntryList.Any())
+                || !string.IsNullOrEmpty(req.CardNameOrCode)
+                || !string.IsNullOrEmpty(req.Status)
+                || !string.IsNullOrEmpty(req.Remarks)
+                || (req.SlpCodes != null && req.SlpCodes.Any())
+                || req.RefundStatus != RefundStatusQuery.All
+                || !string.IsNullOrEmpty(req.SearchText)
+                || req.StartDate.HasValue
+                || req.EndDate.HasValue
+                || (req.UserIds != null && req.UserIds.Any())
+                || !string.IsNullOrEmpty(req.ContinentId)
+                || !string.IsNullOrEmpty(req.CountryId)
+                || !string.IsNullOrEmpty(req.RegionId)
+                || !string.IsNullOrEmpty(req.StateId)
+                || !string.IsNullOrEmpty(req.CityId)
+                || req.DocStartDate.HasValue
+                || req.DocEndDate.HasValue
+                //|| !string.IsNullOrEmpty(req.DeptIndi)
+                || (req.CompSectorFilter != null && req.CompSectorFilter.Any())
+                || (req.CardType != null && req.CardType.Any())
+                || !string.IsNullOrEmpty(req.BelongArea)
+                || (req.CustomerRiskStatus != null && req.CustomerRiskStatus.Count > 0);
+        }
