+        /// <summary>
+        /// 计算应收余额（本币）
+        /// </summary>
+        /// <param name="data">订单基础数据</param>
+        /// <param name="ordrStat">订单统计数据</param>
+        /// <returns>应收余额</returns>
+        private static decimal CalculateReceiptBalance(OrderBasicData data, OrdrStat ordrStat)
+        {
+            var creditAmount = GetNullableValue(ordrStat?.U_Credit_TotalAmt);
+            var receiptAmount = data.U_DocRCTAmount ?? 0;
+            var glAmount = GetNullableValue(ordrStat?.U_GLAmt);
+
+            if (data.DocStatus == "O")
+            {
+                // 订单状态为"O"：订单金额 - 贷项金额 - 收款金额 - GL金额
+                var docTotal = data.DocTotal ?? 0;
+                return docTotal - creditAmount - receiptAmount - glAmount;
+            }
+            else
+            {
+                // 其他状态：交货金额 - 贷项金额 - 收款金额 - GL金额
+                var deliveryAmount = GetNullableValue(ordrStat?.U_Delivery_TotalAmt);
+                return deliveryAmount - creditAmount - receiptAmount - glAmount;
+            }
+        }
+
+        /// <summary>
+        /// 计算应收余额（外币）
+        /// </summary>
+        /// <param name="data">订单基础数据</param>
+        /// <param name="ordrStat">订单统计数据</param>
+        /// <returns>应收余额（外币）</returns>
+        private static decimal CalculateReceiptBalanceFC(OrderBasicData data, OrdrStat ordrStat)
+        {
+            var creditAmountFC = GetNullableValue(ordrStat?.U_Credit_TotalAmtFC);
+            var receiptAmountFC = GetNullableValue(ordrStat?.U_Receipt_TotalAmtFC);
+            var glAmount = GetNullableValue(ordrStat?.U_GLAmt);
+
+            if (data.DocStatus == "O")
+            {
+                // 订单状态为"O"：订单金额 - 贷项金额(退货金额) - 收款金额 - GL金额
+                var docTotalFC = data.DocTotalFC ?? 0;
+                return docTotalFC - creditAmountFC - receiptAmountFC - glAmount;
+            }
+            else
+            {
+                // 其他状态：交货金额 - 贷项金额(退货金额) - 收款金额 - GL金额
+                var deliveryAmountFC = GetNullableValue(ordrStat?.U_Delivery_TotalAmtFC);
+                return deliveryAmountFC - creditAmountFC - receiptAmountFC - glAmount;
+            }
+        }
