+        /// <summary>
+        /// 汇总关联订单数据到主单
+        /// 主单的交货金额、退货金额、应收余额、收款、退款、开票金额是关联订单的总和
+        /// </summary>
+        /// <param name="mainResp"></param>
+        private static void AggregateSubOrdersData(ReceiptReLoadResp mainResp)
+        {
+            if (mainResp.SubOrders == null || mainResp.SubOrders.Count <= 1)
+                return;
+
+            mainResp.OrderAmount = mainResp.SubOrders.Sum(x => x.OrderAmount ?? 0);
+            mainResp.OrderAmountFC = mainResp.SubOrders.Sum(x => x.OrderAmountFC ?? 0);
+
+            mainResp.DeliveryTotalAmount = mainResp.SubOrders.Sum(x => x.DeliveryTotalAmount ?? 0);
+            mainResp.DeliveryTotalAmountFC = mainResp.SubOrders.Sum(x => x.DeliveryTotalAmountFC ?? 0);
+            
+            mainResp.UCreditTotalAmt = mainResp.SubOrders.Sum(x => x.UCreditTotalAmt ?? 0);
+            mainResp.UCreditTotalAmtFC = mainResp.SubOrders.Sum(x => x.UCreditTotalAmtFC ?? 0);
+            
+            mainResp.ReceiptBalance = mainResp.SubOrders.Sum(x => x.ReceiptBalance);
+            mainResp.ReceiptBalanceFC = mainResp.SubOrders.Sum(x => x.ReceiptBalanceFC);
+            
+            // 汇总收款记录
+            mainResp.ReceiptDocEntrys = mainResp.SubOrders
+                .Where(x => x.ReceiptDocEntrys != null)
+                .SelectMany(x => x.ReceiptDocEntrys)
+                .ToList();
+            
+            // 汇总退款记录
+            mainResp.RefundDocEntrys = mainResp.SubOrders
+                .Where(x => x.RefundDocEntrys != null)
+                .SelectMany(x => x.RefundDocEntrys)
+                .ToList();
+
+            mainResp.ReceiptTotalAmount = mainResp.SubOrders.Sum(x => x.ReceiptTotalAmount ?? 0);
+            mainResp.ReceiptTotalAmountFC = mainResp.SubOrders.Sum(x => x.ReceiptTotalAmountFC ?? 0);
+
+            // 汇总开票金额
+            mainResp.BillTotalAmt = mainResp.SubOrders.Sum(x => x.BillTotalAmt ?? 0);
+        }
