+        /// <summary>
+        /// 获取出纳收款关联单据
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        public async Task<TableData<ReceiptRelatedDocResp>> GetRelatedDocs(RecepitGetRelatedDocsReq req)
+        {
+            #region 销售订单查询处理
+            if (!req.DocEntryString.IsNullOrWhiteSpace())
+            {
+                req.DocEntries = await ConvertDocEntryString(req.DocEntryString);
+                if (!req.DocEntries.Any())
+                {
+                    return new TableData<ReceiptRelatedDocResp>() { Data = new ReceiptRelatedDocResp() };
+                }
+            }
+            #endregion
+
+            // 对账的银行流水
+            BankWater water = null;
+            // 流水未入账金额
+            decimal? reconAmt = null;
+            // 默认借方科目
+            GetAcctResp acct = null;
+            ReceiptBaseInfo baseInfo = null;
+
+            #region 有关联流水时，获取默认基本信息
+            if (req.Id != null && req.Id.Count > 0)
+            {
+                if (req.Id.Count > 1)
+                {
+                    throw new InvalidOperationException("收款对账的流水，不支持多选");
+                }
+                var waterId = req.Id[0];
+                water = await UnitWork.FindSingleAsync<BankWater>(x => waterId == x.Water_id);
+                if (water == null)
+                {
+                    throw new InvalidOperationException($"未匹配到id为{waterId}的流水");
+                }
+                reconAmt = water.Amount - water.InAccountAmount;
+
+                var accts = await GetAcctList(water.DealDate, water.LedgerAccount);
+                acct = accts.FirstOrDefault(x => x.AcctCode == water.LedgerAccount);
+                baseInfo = new ReceiptBaseInfo()
+                {
+                    AccountCode = water.LedgerAccount,
+                    Currency = water.Currency == FinanceConsts.CNY ? FinanceConsts.RMB : water.Currency,
+                    Rate = acct.Rate.Value,
+                    PayAmount = water.Amount,
+                    DocDate = water.DealDate,
+                };
+            }
+            #endregion
+
+            var relatedDoc = new List<ReceiptRelatedDoc>();
+            // 销售订单
+            relatedDoc.AddRange(await GetSaleOrders(req, reconAmt, acct));
+            // 保证金
+            relatedDoc.AddRange(await GetBidBonds(req, reconAmt, acct));
+            // 借款
+            relatedDoc.AddRange(await GetLoanRequests(req, reconAmt, acct));
+            // 排序
+            OrderDocResps(relatedDoc, req.OrderType, req.IsAsc);
+            // 匹配默认关联单据
+            MatchOrderNum(relatedDoc, req.ReceiptAmount);
+
+            return new TableData<ReceiptRelatedDocResp>()
+            {
+                Data = new ReceiptRelatedDocResp()
+                {
+                    ReceiptRelatedDocResps = relatedDoc,
+                    BaseInfo = baseInfo,
+                }
+            };
+        }
