+        private async Task<List<int>> ConvertDocEntryString(string keyword)
+        {
+            // 支持的分隔符：左划线，空格，英文逗号，中文逗号，右划线，顿号，英文分号，中文分号
+            var splitItems = new char[] { '/', ' ', ',', '，', '\\', '、', ';', '；', };
+            // 统一分隔符
+            foreach (var s in splitItems)
+            {
+                keyword = keyword.Replace(s, ',');
+            }
+
+            var docEntryStrs = keyword.Split(',');
+            // 商城订单号查询（针对商城线上支付的单）
+            var eshopNoDocEntrys = await EshopNoToDocEntry(docEntryStrs);
+            // 去除前缀
+            return docEntryStrs.Select(x =>
+            {
+                if (x.IsNullOrWhiteSpace())
+                {
+                    return 0;
+                }
+                if (x.StartsWith("SE-"))
+                {
+                    x = x[3..];
+                }
+                return int.TryParse(x, out int tempInt) ? tempInt : 0;
+            }).Concat(eshopNoDocEntrys).Where(r => r != 0).ToList();
+        }
+        /// <summary>
+        /// 
+        /// </summary>
