+        {
+            // 销售订单防止查全表
+            var isSearchSaleOrders = (!req.DocType.HasValue || req.DocType.Value == FinanceReceiptRelatedDocType.FinanceSaleOrder)
+                && (!req.ReceiptAccount.IsNullOrWhiteSpace() || req.DocEntries?.Any() == true || !req.Indicator.IsNullOrWhiteSpace());
+            if (!isSearchSaleOrders)
+            {
+                return new List<ReceiptRelatedDoc>();
+            }
+
+            var idcReq = new GetUnPaySaleOrdersReq()
+            {
+                SaleOrders = req.DocEntries,
+                CardName = req.ReceiptAccount,
+                Indicator = req.Indicator,
+            };
+            var orderFixs = await UnitWork.Find<FinanceOrderFix>(null).ToListAsync();
+            idcReq.fixOrdrs = orderFixs.Select(x => x.DocEntry).ToList();
+            var fixDic = orderFixs.ToDictionary(x => x.DocEntry, x => x.AmountFix);
+            var token = await _httpClientHelper.GetIDCToken();
+            string idcUrl = $"{_configuration.GetValue<string>(Define.IDCApi)}/api/Receipt/GetUnPaySaleOrders";
+            var saleOrderResult = await _httpClientHelper.Post<TableData<List<UnPaySaleOrderResp>, FinanceReceiptMainModel>>(idcUrl, idcReq, token);
+            if (saleOrderResult.Code != 200)
+            {
+                LogHelper.Warn($"获取收款关联销售订单信息失败，原因：{saleOrderResult.Message}");
+                return new List<ReceiptRelatedDoc>();
+            }
+
+            var nameDept = _userDepartMsgHelp.GetUserNameOrgDictionary();
+            
+            // 获取用户映射
+            var userMap = await _userManagerApp.GetNsapUsersAsync();
+            
+            // 构建结果列表
+            var result = saleOrderResult.Data.Select(x => new ReceiptRelatedDoc
+            {
+                DocType = FinanceReceiptRelatedDocType.FinanceSaleOrder,
+                DetailDocTypeName = EnumUtility.GetDescription(FinanceReceiptRelatedDocType.FinanceSaleOrder),
+                DocEntry = x.SaleOrder,
