+                ReceiptAmount = x.ReceiptAmount,
+                Currency = x.Currency,
+                SlpCode = x.SlpCode,
+                SalesMan = nameDept.TryGetValue(x.SalesMan, out var value) ? (value + "-" + x.SalesMan) : x.SalesMan,
+                Erp3UserId = x.Erp3UserId,
+                CustomerSlpCode = x.CustomerSlpCode,
+                CustomerSlpMan = nameDept.TryGetValue(x.CustomerSlpMan, out var customerValue) ? (customerValue + "-" + x.CustomerSlpMan) : x.CustomerSlpMan,
+                CustomerErp3UserId = x.CustomerErp3UserId,
+                Invoices = x.invoices,
+                JournalDetailResps = new GroupdJournal()
+                {
+                    DocEntry = x.SaleOrder,
+                    Remark = string.Empty,
+                    Details = new List<JournalDetailResp>
+                    {
+                        new JournalDetailResp()
+                        {
+                            Code = acct?.AcctCode,
+                            Name = acct?.AcctName,
+                            DocEntry = -1,
+                            CreditAmt = 0,
+                            DebitAmt = reconAmt ?? x.SaleOrderAmount - x.ReceiptAmount,
+                            IsCredit = false,
+                            Currency = x.Currency,
+                            Checked = true,
+                        },
+                        new JournalDetailResp()
+                        {
+                            Code = x.CardCode,
+                            Name = x.CardName,
+                            DocEntry = -1,
+                            CreditAmt = reconAmt ?? x.SaleOrderAmount - x.ReceiptAmount,
+                            DebitAmt = 0,
+                            IsCredit = true,
+                            Currency = x.Currency,
+                            Checked = true,
+                        }
+                    }
+                }
+            }).ToList();
+
+            // 获取SaleManId和CustomerUserId用于查询离职状态
+            foreach (var item in result)
+            {
+                var saleManId = userMap.FirstOrDefault(u => u.NsapUserId == item.Erp3UserId)?.UserID;
+                var customerUserId = userMap.FirstOrDefault(u => u.NsapUserId == item.CustomerErp3UserId)?.UserID;
+                item.SaleManId = saleManId;
+                item.CustomerUserId = customerUserId;
+            }
+
+            // 获取离职状态
+            var userLeaves = await _financeCommonApp.GetUserIsLeave(result.Select(x => x.SaleManId).Distinct().ToList());
+            foreach (var item in result)
+            {
+                item.SaleManIsLeave = userLeaves.FirstOrDefault(x => x.UserId == item.SaleManId)?.IsLeave ?? false;
+            }
+
+            // 获取移交客户的订单
+            var docEntryList = result.Select(r => r.DocEntry).Distinct().ToList();
+            var handCustomerDocEntrys = await UnitWork.Find<SaleOrderPlugin>(x => x.HandCustomer == HandCustomerEnums.Hand && docEntryList.Contains(x.DocEntry)).Select(x => x.DocEntry).ToListAsync();
+            result.Where(x => handCustomerDocEntrys.Contains(x.DocEntry))
+                .ToList()
+                .ForEach(x => x.IsMigratedCustomer = true);
+
+            // 离职售后的单，更改业务员为售后主管
+            await _financeCommonApp.ProcessAfterSalesOrdersWithSupervisorAsync(new ProcessAfterSalesOrdersParams<ReceiptRelatedDoc>
+            {
+                DataList = result,
+                GetDocEntry = x => x.DocEntry,
+                GetIsLeave = x => x.SaleManIsLeave,
+                GetCardCodes = x => x.CardCode,
+                SetIsCsOrder = (x, isCs) => x.IsCsOrder = isCs,
