+                SetSlpCode = (x, val) => x.CustomerSlpCode = val
+            });
+
+            // 如果销售员离职或客户已移交，使用Customer相关字段替换原字段
+            foreach (var item in result)
+            {
+                if (item.SaleManIsLeave || item.IsMigratedCustomer)
+                {
+                    item.SlpCode = item.CustomerSlpCode;
+                    item.SalesMan = item.CustomerSlpMan;
+                    item.Erp3UserId = item.CustomerErp3UserId;
+                    item.SaleManId = item.CustomerUserId;
+                }
+            }
+
+            return result;
+        }
