+        /// <summary>
+        /// 匹配默认入账金额
+        /// </summary>
+        /// <param name="relatedDocResps">记录</param>
+        /// <param name="matchAmount">匹配金额</param>
+        private static void MatchOrderNum(List<ReceiptRelatedDoc> relatedDocResps, decimal? matchAmount)
+        {
+            if (relatedDocResps.Count == 0 || !matchAmount.HasValue || matchAmount.Value == 0)
+            {
+                return;
+            }
+
+            // 优先匹配未收金额匹配的记录，其次匹配未收金额大于匹配金额的记录
+            var amount = matchAmount.Value;
+            var temp = relatedDocResps.FirstOrDefault(r => r.DueAmount == amount)
+                ?? relatedDocResps.FirstOrDefault(r => r.DueAmount > amount);
+            // 处理匹配到的记录
+            if (temp != null)
+            {
+                temp.Checked = true;
+                temp.InAccountAmount = amount;
+                // 如果有发票，还需匹配发票
+                if ((temp.Invoices?.Count ?? 0) > 0)
+                {
+                    var tempAmount = amount;
+                    foreach (var invoice in temp.Invoices)
+                    {
+                        if (tempAmount >= invoice.InvoiceBalance)
+                        {
+                            invoice.InAccountAmount = invoice.InvoiceBalance;
+                            invoice.Checked = true;
+                            tempAmount -= invoice.InAccountAmount;
+                        }
+                        else
+                        {
+                            invoice.InAccountAmount = tempAmount;
+                            invoice.Checked = true;
+                            break;
+                        }
+                    }
+                }
+                // 勾选的移到首位
+                relatedDocResps.Remove(temp);
+                relatedDocResps.Insert(0, temp);
+            }
+        }
+
+        /// <summary>
+        /// 关联单据排序
+        /// </summary>
+        /// <param name="relatedDocResps"></param>
+        /// <param name="orderType"></param>
+        /// <param name="isAsc"></param>
+        private static void OrderDocResps(List<ReceiptRelatedDoc> relatedDocResps, RelatedOrder orderType, bool isAsc)
+        {
+            if (orderType == RelatedOrder.DocTotal)
+            {
+                if (isAsc)
+                    relatedDocResps.Sort((x, y) => x.DocTotal.CompareTo(y.DocTotal));
+                else
+                    relatedDocResps.Sort((x, y) => y.DocTotal.CompareTo(x.DocTotal));
+            }
+            else if (orderType == RelatedOrder.DueAmount)
+            {
+                if (isAsc)
+                    relatedDocResps.Sort((x, y) => x.DueAmount.CompareTo(y.DueAmount));
+                else
+                    relatedDocResps.Sort((x, y) => y.DueAmount.CompareTo(x.DueAmount));
+            }
+            else if (orderType == RelatedOrder.Payee)
+            {
+                if (isAsc)
+                    relatedDocResps.Sort((x, y) => x.Payee.CompareTo(y.Payee));
+                else
+                    relatedDocResps.Sort((x, y) => y.Payee.CompareTo(x.Payee));
+            }
+        }
