+        /// <summary>
+        /// 更新小币种设置
+        /// </summary>
+        /// <returns></returns>
+        public async Task<List<CurrencySetView>> UpdateFinanceCurrencySet(UpdateCurrencySetReq req)
+        {
+            var currentUser = _auth.GetCurrentUser().User;
+            var dbContext = UnitWork.GetDbContext<Financecurrencyset>();
+
+            // 1. 获取中国货币网数据
+            var chinaMoneyData = await GetChinaMoneyCurrencyData();
+            var searchList = chinaMoneyData?.Data?.SearchList ?? new List<string>();
+
+            using (var transaction = await dbContext.Database.BeginTransactionAsync())
+            {
+                try
+                {
+                    // 2. 获取现有币种配置
+                    var existingCurrencies = await UnitWork.Find<Financecurrencyset>(null).ToListAsync();
+                    var existingDict = existingCurrencies.ToDictionary(c => c.CurrCode);
+
+                    // 3. 处理删除的币种
+                    var toDelete = existingCurrencies
+                        .Where(ec => !req.CurrencySets.Any(rc => rc.CurrCode == ec.CurrCode))
+                        .ToList();
+
+                    if (toDelete.Any())
+                    {
+                        await UnitWork.BatchDeleteAsync<Financecurrencyset>(toDelete.ToArray());
+                    }
+
+                    // 4. 处理新增/更新的币种
+                    var toAdd = new List<Financecurrencyset>();
+                    var toUpdate = new List<Financecurrencyset>();
+
+                    foreach (var currency in req.CurrencySets)
+                    {
+                        // 查找匹配的SearchList项
+                        var matchedItem = searchList.FirstOrDefault(item =>
+                            item.Contains(currency.CurrCode, StringComparison.OrdinalIgnoreCase));
+
+                        if (existingDict.TryGetValue(currency.CurrCode, out var existing))
+                        {
+                            // 更新现有记录
+                            existing.CurrName = currency.CurrName;
+                            existing.Updatetime = DateTime.Now;
+                            existing.UpdateUserId = currentUser.Id;
+
+                            // 仅当找到新匹配项时更新Extension
+                            if (!string.IsNullOrEmpty(matchedItem))
+                            {
+                                existing.Extension = matchedItem;
+                            }
+
+                            toUpdate.Add(existing);
+                        }
+                        else
+                        {
+                            // 新增记录
+                            toAdd.Add(new Financecurrencyset
+                            {
+                                CurrCode = currency.CurrCode,
+                                CurrName = currency.CurrName,
+                                CreateTime = DateTime.Now,
+                                CreateUserId = currentUser.Id,
+                                Updatetime = DateTime.Now,
+                                UpdateUserId = currentUser.Id,
+                                Extension = matchedItem ?? string.Empty // 设置匹配项或空字符串
+                            });
+                        }
+                    }
+
+                    // 5. 执行批量操作
+                    if (toAdd.Any())
+                    {
+                        await UnitWork.BatchAddAsync<Financecurrencyset, int>(toAdd.ToArray());
+                    }
+                    if (toUpdate.Any())
+                    {
+                        await UnitWork.BatchUpdateAsync<Financecurrencyset>(toUpdate.ToArray());
+                    }
+
+                    await UnitWork.SaveAsync();
+                    await transaction.CommitAsync();
+                    await SyncSapNewCurrency(toAdd);
+                    return await GetFinanceCurrencySet();
+                }
+                catch (Exception ex)
+                {
+                    await transaction.RollbackAsync();
+                    throw new InvalidOperationException("币种设置更新失败", ex);
+                }
+            }
+        }
