+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        public async Task<Infrastructure.Response<SalesReceiptSummaryListResp>> GetSalesReceiptSummaryAsync(SalesReceiptSummaryReq req)
+        {
+            try
+            {
+                var query =
+                    from orct in UnitWork.Find<ORCT>(null)
+                    .WhereIf(req.ReceiptStartDate.HasValue,x=>x.DocDate>=req.ReceiptStartDate)
+                    .WhereIf(req.ReceiptEndDate.HasValue,x=>x.DocDate<=req.ReceiptEndDate)
+                    join ocrd in UnitWork.Find<OCRD>(null) on orct.CardCode equals ocrd.CardCode
+                    join ordr in UnitWork.Find<ORDR>(null) on orct.U_XSDD equals ordr.DocEntry into orderef
+                    from a in orderef.DefaultIfEmpty()
+                    join oidc in UnitWork.Find<OIDC>(null) on a.Indicator equals oidc.Code into oidcef
+                    from c in oidcef.DefaultIfEmpty()
+                    join oslp in UnitWork.Find<OSLP>(null) on a.SlpCode equals oslp.SlpCode into ordrss
+                    from s in ordrss.DefaultIfEmpty()
+                    select new
+                    {
+                        SlpCode = a.SlpCode ?? Convert.ToInt32(orct.U_U_XSDBCode ?? "0"),
+                        SlpName = s.SlpName ?? orct.U_XSDB,
+                        Indicator = a.Indicator,
+                        IndicatorName = c.Name,
+                        ReceiptAmount = orct.DocTotal.Value,
+                        ReceiptAmountFc = orct.DocTotalFC.Value,
+                        ReceiptDocCur = orct.DocCurr,
+                        ReceiptDocDate = orct.DocDate.Value,
+                        ReceiptDocEntry = orct.DocEntry,
+                        SaleDocEntry = orct.U_XSDD, // 新增：销售订单号
+                        Canceled = orct.Canceled
+                    };
+
+                //  只统计有效收款（未取消）
+                query = query.Where(x => x.Canceled == "N");
+
+                // 标识筛选
+                query = ApplyIndicatorFilters(query, req.Indicator,req.IndicatorList);
+
+                // 销售员编码批量查询筛选
+                if (req.SlpCodeList != null && req.SlpCodeList.Count > 0)
+                {
+                    query = query.Where(x => req.SlpCodeList.Contains(x.SlpCode));
+                }
+
+                var rawList = await query.ToListAsync();
+
+                // 单个回款金额筛选（在分组前进行）
+                if (req.IsSingleReceipt && (req.AmountMin.HasValue || req.AmountMax.HasValue))
+                {
+                    rawList = rawList.Where(x =>
+                    {
