+        /// <summary>
+        /// 对销售员回款汇总结果进行动态排序
+        /// </summary>
+        /// <param name="result"></param>
+        /// <param name="sortName"></param>
+        /// <param name="sortOrder"></param>
+        /// <returns></returns>
+        private static List<SalesReceiptSummaryResp> ApplySorting(List<SalesReceiptSummaryResp> result, string sortName, string sortOrder)
+        {
+            if (string.IsNullOrEmpty(sortName))
+            {
+                return result.OrderByDescending(x => x.TotalReceiptAmount).ToList();
+            }
+
+            var propertyInfo = typeof(SalesReceiptSummaryResp).GetProperty(sortName,
+                System.Reflection.BindingFlags.IgnoreCase | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
+
+            if (propertyInfo == null)
+            {
+                return result.OrderByDescending(x => x.TotalReceiptAmount).ToList();
+            }
+
+            bool isAsc = string.Equals(sortOrder, "asc", StringComparison.OrdinalIgnoreCase);
+
+            return isAsc
+                 ? result.OrderBy(r => propertyInfo.GetValue(r, null)).ToList()
+                 : result.OrderByDescending(r => propertyInfo.GetValue(r, null)).ToList();
+        }
+        /// <summary>
+        /// 汇总结果的内存二次筛选（业务员搜索、入职时长、金额范围）
+        /// </summary>
+        /// <param name="result"></param>
+        /// <param name="searchSlpCodes"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static List<SalesReceiptSummaryResp> FilterSummaryResult(
+            List<SalesReceiptSummaryResp> result,
+            List<int> searchSlpCodes,
+            SalesReceiptSummaryReq req)
+        {
+            var query = result.AsEnumerable();
+            // 业务员关键字过滤
+            if (searchSlpCodes != null && searchSlpCodes.Any())
+            {
+                query = query.Where(x => searchSlpCodes.Contains(x.SlpCode));
+            }
+
+            // 销售员ID批量筛选
+            if (req.SaleManIdList != null && req.SaleManIdList.Any())
+            {
+                query = query.Where(x => x.SaleManId != null && req.SaleManIdList.Contains(x.SaleManId));
+            }
+
+            // 入职时长筛选
+            if (req.TenureMonthMin.HasValue)
+            {
+                query = query.Where(x => x.TenureMonths >= req.TenureMonthMin.Value);
+            }
+            if (req.TenureMonthMax.HasValue)
+            {
+                query = query.Where(x => x.TenureMonths <= req.TenureMonthMax.Value);
+            }
+
+            // 金额范围筛选（只在非单个回款模式下执行）
+            if (!req.IsSingleReceipt)
+            {
+                if (req.AmountMin.HasValue)
+                {
+                    query = query.Where(x => x.TotalReceiptAmount >= req.AmountMin.Value).ToList();
+                }
+                if (req.AmountMax.HasValue)
+                {
+                    query = query.Where(x => x.TotalReceiptAmount <= req.AmountMax.Value).ToList();
+                }
+            }
+            return query.ToList();
+        }
+        /// <summary>
+        /// 标识筛选
+        /// </summary>
+        /// <typeparam name="T"></typeparam>
+        /// <param name="query"></param>
+        /// <param name="indicator"></param>
+        /// <param name="indicatorList"></param>
+        /// <returns></returns>
+        private static IQueryable<T> ApplyIndicatorFilters<T>(IQueryable<T> query, string indicator, List<string> indicatorList)
+        {
+            // 处理单个标识
+            if (!string.IsNullOrEmpty(indicator) && indicator != "N")
+            {
+                query = query.Where(x => EF.Property<string>(x, "Indicator") == indicator);
+            }
+            else if (indicator == "N")
+            {
+                query = query.Where(x => string.IsNullOrEmpty(EF.Property<string>(x, "Indicator")));
+            }
+
+            // 处理标识列表
+            if (indicatorList != null && indicatorList.Count > 0)
+            {
+                if (indicatorList.Contains("N"))
+                {
+                    query = query.Where(x => string.IsNullOrEmpty(EF.Property<string>(x, "Indicator"))
+                                             || indicatorList.Contains(EF.Property<string>(x, "Indicator")));
+                }
+                else
+                {
+                    query = query.Where(x => indicatorList.Contains(EF.Property<string>(x, "Indicator")));
+                }
+            }
+            return query;
+        }
+
+        /// <summary>
+        /// 过账时间筛选
+        /// </summary>
+        /// <typeparam name="T"></typeparam>
+        /// <param name="rawList"></param>
+        /// <param name="startDate"></param>
+        /// <param name="endDate"></param>
+        /// <param name="dateSelector"></param>
+        /// <returns></returns>
+        private static List<T> FilterByDocDate<T>(IEnumerable<T> rawList, DateTime? startDate, DateTime? endDate, Func<T, DateTime> dateSelector)
+        {
+            var result = rawList;
+            if (startDate.HasValue)
+            {
+                result = result.Where(x => dateSelector(x) >= startDate.Value);
+            }
+            if (endDate.HasValue)
+            {
+                result = result.Where(x => dateSelector(x) <= endDate.Value);
+            }
+            return result.ToList();
+        }
+        /// <summary>
+        /// 业务员关键字搜索
+        /// </summary>
+        /// <param name="grouped"></param>
