+        private static List<int> GetSearchSlpCodes(IEnumerable<dynamic> grouped, string searchText, Dictionary<string, string> orgDict)
+        {
+            if (string.IsNullOrWhiteSpace(searchText)) return new List<int>();
+
+            var parts = searchText.Split("-");
+            var searchUserName = parts.Length > 1 ? parts[1] : searchText;
+            var searchOrg = parts.Length > 1 ? parts[0] : string.Empty;
+
+            return grouped.Where(g =>
+            {
+                string slpName = g.SlpName ?? "";
+                string deptName = orgDict.TryGetValue(slpName, out var org) ? org : "";
+
+                if (!string.IsNullOrEmpty(searchOrg))
+                {
+                    return deptName.Contains(searchOrg) && slpName.Contains(searchUserName);
+                }
+                return slpName.Contains(searchUserName) || deptName.Contains(searchUserName);
+            }).Select(g => (int)g.SlpCode).ToList();
+        }
