+                            .Where(x => !string.IsNullOrEmpty(x))
+                            .Distinct();                                     
+            string erpUserIdSql = $@"select su.user_id,su.sale_id
+                                from nsap_bone.crm_oslp c
+                                inner join sbo_user su on c.SlpCode = su.sale_id
