+        /// <summary>
+        /// 匹配并填充 销售员和业务员的Erp3UserId和SaleManId
+        /// </summary>
+        /// <param name="result"></param>
+        /// <param name="erpUserIdList"></param>
+        /// <returns></returns>
+        private async Task MatchAndFillUserIdsAsync(List<ReceiptDtoResp> result, IEnumerable<sbo_user> erpUserIdList)
+        {
+            if (result == null || result.Count == 0 || erpUserIdList == null) return;
+
+            var userMap = await _userManagerApp.GetNsapUsersAsync();
+
+            var erpDict = erpUserIdList
+                .Where(x => x.sale_id != null)
+                .GroupBy(x => x.sale_id)
+                .ToDictionary(g => g.Key, g => g.First().user_id);
+
+            var userDict = userMap
+                .Where(u => u.NsapUserId != null)
+                .GroupBy(u => u.NsapUserId)
+                .ToDictionary(g => g.Key, g => g.First().UserID);
+
+            foreach (var item in result)
+            {
+                item.Erp3UserId = (int)(erpDict.TryGetValue(item.SlpCode, out var erpId) ? erpId : 0);
+                item.CustomerErp3UserId = (int)(item.CustomerSlpCode != null && erpDict.TryGetValue(item.CustomerSlpCode, out var cErpId) ? cErpId : 0);
+
+                item.SaleManId = item.Erp3UserId != null && userDict.TryGetValue(item.Erp3UserId, out var saleId) ? saleId : null;
+                item.CustomerSaleManId = item.CustomerErp3UserId != null && userDict.TryGetValue(item.CustomerErp3UserId, out var cSaleId) ? cSaleId : null;
+            }
+        }
+        /// <summary>
+        /// 处理业务员离职、客户移交、离职售后分配，并根据权限过滤单据
+        /// </summary>
+        /// <param name="result"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<List<ReceiptDtoResp>> ProcessResignationAndTransferAsync(List<ReceiptDtoResp> result, ReceiptLoadIdcReq req)
+        {
+            if (result == null || result.Count == 0) return result;
+
+            var userLeaves = await _financeCommonApp.GetUserIsLeave(result.Select(x => x.SaleManId).Distinct().ToList());
+            var leaveDict = userLeaves
+                            .Where(x => x.UserId != null)
+                            .GroupBy(x => x.UserId)
+                            .ToDictionary(g => g.Key, g => g.First().IsLeave);
+            foreach (ReceiptDtoResp item in result)
+            {
+                item.SaleManIsLeave = item.SaleManId != null && leaveDict.GetValueOrDefault(item.SaleManId);
+            }
+
+            var docEntryList = result.Select(r => r.SaleDocEntry).Distinct().ToList();
+
+            //离职售后的单，更改业务员为售后主管
+            await _financeCommonApp.ProcessAfterSalesOrdersWithSupervisorAsync(new ProcessAfterSalesOrdersParams<ReceiptDtoResp>
+            {
+                DataList = result,
+                GetDocEntry = x => x.SaleDocEntry ?? 0,
+                GetIsLeave = x => x.SaleManIsLeave,
+                GetCardCodes = x => x.CardCode,
+                SetIsCsOrder = (x, isCs) => x.IsCsOrder = isCs,
+                SetErp3UserId = (x, val) => x.CustomerErp3UserId = val ?? 0,
+                SetSalePersonUserId = (x, val) => x.CustomerSaleManId = val,
+                SetSlpName = (x, val) => x.CustomerSlpMan = val,
+                SetSlpCode = (x, val) => x.CustomerSlpCode = val
+            });
+            //移交的单
+            var handCustomerDocEntrys = await UnitWork.Find<SaleOrderPlugin>(x => x.HandCustomer == HandCustomerEnums.Hand && docEntryList.Contains(x.DocEntry)).Select(x => x.DocEntry).ToListAsync();
+            result.Where(x => x.SaleDocEntry != null && handCustomerDocEntrys.Contains((int)x.SaleDocEntry))
+                .ToList()
+                .ForEach(x => x.IsMigratedCustomer = true);
+
+            if (req.SlpCodes != null && req.SlpCodes.Count > 0)
+            {
+                result = result.Where(x =>
+                    //自己slpcode的单
+                    req.SlpCodes.Contains(x.SlpCode.ToString()) ||
+                    //离职的并且CustomerSlpCode是自己slpcode的单
+                    (x.CustomerSlpCode != null && x.SaleManIsLeave && req.SlpCodes.Contains(x.CustomerSlpCode.ToString())) ||
+                    //移交的单并且CustomerSlpCode是自己slpcode的单
+                    (x.SaleDocEntry != null && x.CustomerSlpCode != null && handCustomerDocEntrys.Contains((int)x.SaleDocEntry) && req.SlpCodes.Contains(x.CustomerSlpCode.ToString()))
+                )
+                .ToList();
+            }
+
+            HandleCustomer(result);
+
+            return result;
+        }
+        /// <summary>
+        /// 收款时间筛选
+        /// </summary>
+        /// <param name="list"></param>
+        /// <param name="startDate"></param>
+        /// <param name="endDate"></param>
+        /// <returns></returns>
+        private static List<ReceiptDtoResp> FilterByReceiptDate(List<ReceiptDtoResp> list, DateTime? startDate, DateTime? endDate)
+        {
+            if (!startDate.HasValue && !endDate.HasValue) return list;
+
+            return list.Where(x =>
+            {
+                if (startDate.HasValue)
+                {
+                    x.ReceiptDocEntrys = x.ReceiptDocEntrys.Where(r => r.CreateTime >= startDate.Value).ToList();
+                }
+                if (endDate.HasValue)
+                {
+                    x.ReceiptDocEntrys = x.ReceiptDocEntrys.Where(r => r.CreateTime <= endDate.Value).ToList();
+                }
+                return x.ReceiptDocEntrys.Any();
+            }).ToList();
+        }
+
+        /// <summary>
+        /// 过账时间筛选
+        /// </summary>
+        /// <param name="list"></param>
+        /// <param name="docStartDate"></param>
+        /// <param name="docEndDate"></param>
+        /// <returns></returns>
+        private static List<ReceiptDtoResp> FilterByPostingDate(List<ReceiptDtoResp> list, DateTime? docStartDate, DateTime? docEndDate)
+        {
+            if (!docStartDate.HasValue && !docEndDate.HasValue) return list;
+
+            return list.Where(x =>
+            {
+                if (docStartDate.HasValue)
+                {
+                    x.ReceiptDocEntrys = x.ReceiptDocEntrys.Where(r => r.DocDate >= docStartDate.Value).ToList();
+                }
+                if (docEndDate.HasValue)
+                {
+                    x.ReceiptDocEntrys = x.ReceiptDocEntrys.Where(r => r.DocDate <= docEndDate.Value).ToList();
+                }
+                return x.ReceiptDocEntrys.Any();
+            }).ToList();
+        }
