+        /// <summary>
+        /// 条件筛选
+        /// </summary>
+        /// <param name="query"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static (IQueryable<dynamic>, List<int?> queInt) ApplyQueryFilters(IQueryable<ReceiptQueryModel> query, ReceiptLoadIdcReq req)
+        {
+            var queInt = req.RefundFilters?.Where(f => f.OrderId.HasValue).Select(f => f.OrderId);
+            var queCordCode = req.RefundFilters?.Where(f => !f.OrderId.HasValue).Select(f => f.CardCode);
+
+
+            query = query
+                .WhereIf(!string.IsNullOrEmpty(req.Indicator) && req.Indicator != "N", x => x.Indicator == req.Indicator)
+                .WhereIf(req.Indicator == "N", x => x.Indicator == string.Empty || x.Indicator == null)
+                .WhereIf(req.ReceiptDocEntry.HasValue, x => x.SubReceiptDocEntry == req.ReceiptDocEntry.Value)
+                .WhereIf(req.SaleDocEntry.HasValue, x => x.SaleDocEntry == req.SaleDocEntry.Value)
+                .WhereIf(!string.IsNullOrEmpty(req.CardNameOrCode), x => x.CardCode.Contains(req.CardNameOrCode) || x.CardName.Contains(req.CardNameOrCode))
+                .WhereIf(!string.IsNullOrEmpty(req.Remarks), x => x.Remarks.Contains(req.Remarks))
+                .WhereIf(!string.IsNullOrEmpty(req.PrintStatus), x => x.Printed == req.PrintStatus)
+                .WhereIf(string.IsNullOrEmpty(req.CancelStatus), x => x.Canceled == "N") //默认是不包含已取消的
+                .WhereIf(!string.IsNullOrEmpty(req.CancelStatus), x => x.Canceled == req.CancelStatus)
+                .WhereIf(req.IndicatorList != null && req.IndicatorList.Count > 0 && req.IndicatorList.Contains("N"), x => (x.Indicator == string.Empty || x.Indicator == null) || req.IndicatorList.Contains(x.Indicator))
+                .WhereIf(req.IndicatorList != null && req.IndicatorList.Count > 0 && !req.IndicatorList.Contains("N"), x => req.IndicatorList.Contains(x.Indicator))
+                .WhereIf(req.SaleOrderIds != null && req.SaleOrderIds.Count > 0, x => req.SaleOrderIds.Contains((int)x.SaleDocEntry))
+                .WhereIf(req.SaleDocEntryList != null && req.SaleDocEntryList.Count > 0, x => req.SaleDocEntryList.Contains(x.SaleDocEntry.Value))
+                .WhereIf(req.RefundFilters?.Any() == true, x => queInt.Contains(x.SaleDocEntry) || (x.SaleDocEntry == null && queCordCode.Contains(x.CardCode)));
+                
+            return (query, queInt?.ToList());
+        }
