+        public async Task<TableData<List<ReceiptReLoadResp>>> ReLoad(ReceiptLoadReq req)
+        {
+            // 判断是否有除page和limit之外的搜索条件
+            var hasOtherFilters = HasOtherSearchFilters(req);
+            
+            if (hasOtherFilters)
+            {
+                // 有其他搜索条件，需要调用两次Load来获取关联订单
+                return await ReLoadWithFilters(req);
