+        /// <summary>
+        /// 处理完全没有销售订单关联的收款记录分支
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<TableData<List<ReceiptReLoadResp>>> HandleNoSaleOrdersBranch(List<ReceiptDtoResp> allReceipts, ReceiptLoadReq req)
+        {
+            var data = allReceipts.Select(r => ConvertToReLoadResp(r, true)).ToList();
+            var count = data.Count;
+            var pagedData = data.Skip((req.page - 1) * req.limit).Take(req.limit).ToList();
+
+            var dataForFill = new List<ReceiptDtoResp>();
+            foreach (var item in pagedData)
+            {
+                dataForFill.Add(item);
+                if (item.SubOrders != null) dataForFill.AddRange(item.SubOrders);
+            }
+            await FillExtraData(dataForFill, req.RefundStatus);
+            return new TableData<List<ReceiptReLoadResp>> { Data = pagedData, Count = count, Code = 200 };
+        }
+        /// <summary>
+        /// 递归/双向收集所有相关的订单ID（向上追溯主单，向下扩展子单）
+        /// </summary>
+        /// <param name="saleDocEntries"></param>
+        /// <param name="saleOrderInfos"></param>
+        /// <param name="orderRelations"></param>
+        /// <returns></returns>
+        private async Task<HashSet<int>> CollectAllRelatedOrderIds(List<int> saleDocEntries, dynamic saleOrderInfos, Dictionary<int, string> orderRelations)
+        {
+            var allRelatedOrderIds = new HashSet<int>(saleDocEntries);
+
+            // 向上追溯主单
+            foreach (var order in saleOrderInfos)
+            {
+                if (!string.IsNullOrEmpty(order.RelevanceOrderNos))
+                {
+                    var mainIds = ParseOrderIds(order.RelevanceOrderNos);
+                    foreach (var mainId in mainIds)
+                    {
+                        allRelatedOrderIds.Add(mainId);
+                    }
+                }
+            }
+
+            // 向下扩展子单
+            var mainOrderIds = allRelatedOrderIds.ToList();
+            var allSubOrderInfos = await UnitWork.Find<SaleOrderInfo>(
+                x => !string.IsNullOrEmpty(x.RelevanceOrderNos) && !x.IsDeleted)
+                .Select(x => new { x.OrderId, x.RelevanceOrderNos })
+                .ToListAsync();
+
+            foreach (var subOrder in allSubOrderInfos)
+            {
+                var mainIds = ParseOrderIds(subOrder.RelevanceOrderNos);
+                if (mainIds.Any(mainId => mainOrderIds.Contains(mainId)))
+                {
+                    allRelatedOrderIds.Add(subOrder.OrderId);
+                    if (!orderRelations.ContainsKey(subOrder.OrderId))
+                    {
+                        orderRelations[subOrder.OrderId] = subOrder.RelevanceOrderNos;
+                    }
+                }
+            }
+            return allRelatedOrderIds;
+        }
+        /// <summary>
+        /// 找出并补充那些有子单收款但主单没收款记录的主单数据
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="allRelatedOrderIds"></param>
+        /// <param name="orderRelations"></param>
+        /// <returns></returns>
+        private async Task SupplementMissingMainOrders(List<ReceiptDtoResp> allReceipts, HashSet<int> allRelatedOrderIds, Dictionary<int, string> orderRelations)
+        {
+            var returnedOrderIds = allReceipts
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value)
+                .Distinct()
+                .ToHashSet();
+
+            var missingOrderIds = allRelatedOrderIds
+                .Where(orderId => !returnedOrderIds.Contains(orderId))
+                .ToList();
+
+            if (!missingOrderIds.Any()) return;
+
+            // 只补充主单（子单会在ProcessReLoadData中通过关系自动关联）
+            var missingMainOrderIds = missingOrderIds
+                .Where(orderId => !orderRelations.ContainsKey(orderId) || string.IsNullOrEmpty(orderRelations[orderId]))
+                .ToList();
+
+            if (!missingMainOrderIds.Any()) return;
+            
+            var missingMainOrders = await BuildReceiptForOrdersWithoutPayment(missingMainOrderIds);
+
+            // 只补充那些有子单收款的主单
+            var mainOrdersWithSubPayment = new List<ReceiptDtoResp>();
+            foreach (var missingOrder in missingMainOrders)
+            {
+                if (!missingOrder.SaleDocEntry.HasValue) continue;
+
+                var orderId = missingOrder.SaleDocEntry.Value;
+                var hasSubOrderWithPayment = returnedOrderIds.Any(returnedId =>
+                {
+                    if (orderRelations.TryGetValue(returnedId, out var mainIdsStr))
+                    {
+                        var mainIds = ParseOrderIds(mainIdsStr);
+                        return mainIds.Contains(orderId);
+                    }
+                    return false;
+                });
+
+                if (hasSubOrderWithPayment)
+                {
+                    mainOrdersWithSubPayment.Add(missingOrder);
+                }
+            }
+
+            allReceipts.AddRange(mainOrdersWithSubPayment);
+            
+            
+        }
+        /// <summary>
+        /// 有其他搜索条件时的ReLoad（调用两次Load获取关联订单）
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<TableData<List<ReceiptReLoadResp>>> ReLoadWithFilters(ReceiptLoadReq req)
+        {
+            var tableData = new TableData<List<ReceiptReLoadResp>>();
+            
+            // 如果直接搜索订单号，先获取所有关联订单
+            var initialDocEntries = ExtractInitialDocEntries(req);
+
+            // 如果有直接搜索的订单号，先获取所有关联订单
+            if (initialDocEntries.Any())
+            {
+                var (allRelatedFromSearch, _) = await CollectAllRelatedOrdersWithInfo(initialDocEntries.Distinct().ToList());
+                // 更新请求参数，包含所有关联订单
+                req.SaleDocEntryList = allRelatedFromSearch.ToList();
+                req.SaleDocEntry = null; // 清空单个订单号，使用列表
+            }
+            
+            //  先调用Load获取筛选条件匹配的收款数据
+            var originalReq = new ReceiptLoadReq
+            {
+                Indicator = req.Indicator,
+                IndicatorList = req.IndicatorList,
+                ReceiptDocEntry = req.ReceiptDocEntry,
+                SaleDocEntry = req.SaleDocEntry,
+                SaleDocEntryList = req.SaleDocEntryList,
+                CardNameOrCode = req.CardNameOrCode,
+                Status = req.Status,
+                Remarks = req.Remarks,
+                SlpCodes = req.SlpCodes,
+                RefundStatus = req.RefundStatus,
+                SearchText = req.SearchText,
+                StartDate = req.StartDate,
+                EndDate = req.EndDate,
+                UserIds = req.UserIds,
+                ContinentId = req.ContinentId,
+                CountryId = req.CountryId,
+                RegionId = req.RegionId,
+                StateId = req.StateId,
+                CityId = req.CityId,
+                DocStartDate = req.DocStartDate,
+                DocEndDate = req.DocEndDate,
+                DeptIndi = req.DeptIndi,
+                CompSectorFilter = req.CompSectorFilter,
+                CardType = req.CardType,
+                BelongArea = req.BelongArea,
+                page = 1,
+                limit = MaxQueryLimit
+            };
+            
+            var allData = await LoadLocal(originalReq, true);
+            
+            // 如果第一次查询无结果，但有直接搜索的订单号，尝试构建虚拟收款记录
+            if ((allData.Code != 200 || allData.Data == null || !allData.Data.Any()) && initialDocEntries.Any())
+            {
+                var missingOrders = await BuildReceiptForOrdersWithoutPayment(initialDocEntries);
+                if (missingOrders.Any())
+                {
+                    allData.Data = missingOrders;
+                    allData.Code = 200;
+                }
+                else
+                {
+                    tableData.Code = allData.Code;
+                    tableData.Message = allData.Message;
+                    tableData.Data = new List<ReceiptReLoadResp>();
+                    tableData.Count = 0;
+                    return tableData;
+                }
+            }
+            else if (allData.Code != 200 || allData.Data == null || !allData.Data.Any())
+            {
+                tableData.Code = allData.Code;
+                tableData.Message = allData.Message;
+                tableData.Data = new List<ReceiptReLoadResp>();
+                tableData.Count = 0;
+                return tableData;
+            }
+
+            var filteredReceipts = allData.Data;
+            
+            //  获取筛选结果中的销售订单号
+            var filteredDocEntries = filteredReceipts
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value)
+                .Distinct()
+                .ToList();
+
+            if (!filteredDocEntries.Any())
+            {
+                tableData.Data = filteredReceipts.Select(r => ConvertToReLoadResp(r, true)).ToList();
+                tableData.Count = tableData.Data.Count;
+                tableData.Data = tableData.Data.Skip((req.page - 1) * req.limit).Take(req.limit).ToList();
+                
+                var dataForFill = new List<ReceiptDtoResp>();
+                foreach (var item in tableData.Data)
+                {
+                    dataForFill.Add(item);
+                    if (item.SubOrders != null) dataForFill.AddRange(item.SubOrders);
+                }
+                await FillExtraData(dataForFill, req.RefundStatus);
+                return tableData;
+            }
+
+            // 完整收集所有关联订单（向上找主单、向下找子单）+ 返回订单关系信息
+            var (allRelatedOrderIds, orderRelations) = await CollectAllRelatedOrdersWithInfo(filteredDocEntries);
+
+            // 查询所有关联订单的收款数据（第二次调用Load）
+            var relatedOrderIdsList = allRelatedOrderIds.ToList();
+            var relatedReq = new ReceiptLoadReq
+            {
+                Indicator = req.Indicator,
+                IndicatorList = req.IndicatorList,
+                SaleDocEntryList = relatedOrderIdsList,
+                ReceiptDocEntry = req.ReceiptDocEntry,
+                SaleDocEntry = req.SaleDocEntry,
+                CardNameOrCode = req.CardNameOrCode,
+                Status = req.Status,
+                Remarks = req.Remarks,
+                SlpCodes = req.SlpCodes,
+                RefundStatus = req.RefundStatus,
+                SearchText = req.SearchText,
+                StartDate = req.StartDate,
+                EndDate = req.EndDate,
+                UserIds = req.UserIds,
+                ContinentId = req.ContinentId,
+                CountryId = req.CountryId,
+                RegionId = req.RegionId,
+                StateId = req.StateId,
+                CityId = req.CityId,
+                DocStartDate = req.DocStartDate,
+                DocEndDate = req.DocEndDate,
+                DeptIndi = req.DeptIndi,
+                CompSectorFilter = req.CompSectorFilter,
+                CardType = req.CardType,
+                BelongArea = req.BelongArea,
+                page = 1,
+                limit = MaxQueryLimit
+            };
+
+            var relatedData = await LoadLocal(relatedReq, true);
+            var allReceipts = relatedData.Data ?? new List<ReceiptDtoResp>();
+
+            // 合并没有SaleDocEntry的数据
+            var receiptsWithoutDocEntry = filteredReceipts.Where(x => !x.SaleDocEntry.HasValue).ToList();
+            allReceipts.AddRange(receiptsWithoutDocEntry);
+
+            // 补充缺失的记录（有订单无收款的情况）
+            await SupplementMissingOrderReceipts(allReceipts, allRelatedOrderIds.ToList());
+
+            // 复用已查询的订单关系信息（避免重复查询 SaleOrderInfo）
+            var saleOrderInfos = BuildSaleOrderInfosForProcess(allReceipts, orderRelations);
+
+            // 后续处理逻辑
+            return await ProcessReLoadData(allReceipts, saleOrderInfos, req);
+        }
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static List<int> ExtractInitialDocEntries(ReceiptLoadReq req)
+        {
+            var initialDocEntries = new List<int>();    
+            if (req.SaleDocEntry.HasValue)
+            {
+                initialDocEntries.Add(req.SaleDocEntry.Value);
+            }
+            if (req.SaleDocEntryList?.Any() == true)
+            {
+                initialDocEntries.AddRange(req.SaleDocEntryList);
+            }
+            return initialDocEntries;
+        }
+        /// <summary>
+        /// 补充子单
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="relatedOrderIdsList"></param>
+        /// <returns></returns>
+        private async Task SupplementMissingOrderReceipts(List<ReceiptDtoResp> allReceipts, List<int> relatedOrderIdsList)
+        {
+            var existingOrderIds = allReceipts
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value)
+                .Distinct()
+                .ToHashSet();
+
+            // 找出在关联订单中但没有收款记录的订单
+            var missingOrderIds = relatedOrderIdsList
+                .Where(orderId => !existingOrderIds.Contains(orderId))
+                .Distinct()
+                .ToList();
+
+            if (!missingOrderIds.Any()) return;
+
+            var missingOrders = await BuildReceiptForOrdersWithoutPayment(missingOrderIds);
+            var ordersToAdd = missingOrders
+                .Where(x => x.SaleDocEntry.HasValue && existingOrderIds.Add(x.SaleDocEntry.Value))
+                .ToList();
+
+            allReceipts.AddRange(ordersToAdd);
+        }
+        /// <summary>
+        /// 为没有收款记录的订单构建虚拟的收款响应对象
+        /// </summary>
+        /// <param name="orderIds">订单号列表</param>
+        /// <returns>虚拟的收款响应对象列表</returns>
+        private async Task<List<ReceiptDtoResp>> BuildReceiptForOrdersWithoutPayment(List<int> orderIds)
+        {
+            // 查询订单基本信息（简化查询，只获取必要字段）
+            var ordersData = await QueryOrdersBasicData(orderIds);
+
+            // 在内存中进行复杂计算和映射
+            var result = ordersData.Select(data => MapToReceiptResponse(data)).ToList();
+
+            return result;
+        }
