+        /// <summary>
+        /// 查询订单基础数据（无收款记录场景）
+        /// </summary>
+        /// <param name="orderIds">订单号列表</param>
+        /// <returns>订单基础数据查询结果</returns>
+        private async Task<List<OrderBasicData>> QueryOrdersBasicData(List<int> orderIds)
+        {
+            var ordersQuery = from ordr in UnitWork.Find<ORDR>(x => orderIds.Contains(x.DocEntry))
+                              join ocrd in UnitWork.Find<OCRD>(null) on ordr.CardCode equals ocrd.CardCode
+                              join ordrStat in UnitWork.Find<OrdrStat>(null) on ordr.DocEntry equals Convert.ToInt32(ordrStat.Code) into ordrStatef
+                              from b in ordrStatef.DefaultIfEmpty()
+                              join oidc in UnitWork.Find<OIDC>(null) on ordr.Indicator equals oidc.Code into oidcef
+                              from c in oidcef.DefaultIfEmpty()
+                              join oslp in UnitWork.Find<OSLP>(null) on ordr.SlpCode equals oslp.SlpCode into ordrss
+                              from s in ordrss.DefaultIfEmpty()
+                              join oslpCustomer in UnitWork.Find<OSLP>(null) on ocrd.SlpCode equals oslpCustomer.SlpCode into customerSlps
+                              from cs in customerSlps.DefaultIfEmpty()
+                              select new OrderBasicData
+                              {
+                                  // 订单基本信息
+                                  DocEntry = ordr.DocEntry,
+                                  CardCode = ordr.CardCode,
+                                  CardName = ordr.CardName,
+                                  Indicator = ordr.Indicator,
+                                  IndicatorName = c.Name,
+                                  DocTotal = ordr.DocTotal,
+                                  DocTotalFC = ordr.DocTotalFC,
+                                  DocCur = ordr.DocCur,
+                                  SaleMan = s.SlpName,
+                                  SlpCode = ordr.SlpCode ?? 0,
+                                  UpdateDate = ordr.UpdateDate,
+                                  CreateDate = ordr.CreateDate,
+                                  DocRate = ordr.DocRate,
+                                  DocStatus = ordr.DocStatus,
+                                  U_DocRCTAmount = ordr.U_DocRCTAmount,
+
+                                  // OrdrStat 相关字段
+                                  OrdrStat = b,
+
+                                  // 客户销售员信息
+                                  CustomerSlpCode = ocrd.SlpCode,
+                                  CustomerSlpMan = cs.SlpName,
+                              };
+
+            return await ordersQuery.ToListAsync();
+        }
