+        /// <summary>
+        /// 将订单基础数据映射为收款响应对象
+        /// </summary>
+        /// <param name="data">订单基础数据</param>
+        /// <returns>收款响应对象</returns>
+        private static ReceiptDtoResp MapToReceiptResponse(OrderBasicData data)
+        {
+            var ordrStat = data.OrdrStat;
+
+            return new ReceiptDtoResp
+            {
+                // 基本信息
+                SaleDocEntry = data.DocEntry,
+                CardCode = data.CardCode,
+                CardName = data.CardName,
+                Indicator = data.Indicator,
+                IndicatorName = data.IndicatorName,
+                OrderAmount = data.DocTotal,
+                OrderAmountFC = data.DocTotalFC,
+                DocCur = data.DocCur,
+                SaleMan = data.SaleMan,
+                SlpCode = data.SlpCode,
+                UpdateTime = data.UpdateDate,
+                CreateTime = data.CreateDate,
+                DocRate = data.DocRate,
+                DocStatus = data.DocStatus,
+
+                // 收款相关字段：没有收款记录，设置为0或空
+                ReceiptTotalAmount = data.U_DocRCTAmount ?? 0,
+                ReceiptTotalAmountFC = GetNullableValue(ordrStat?.U_Receipt_TotalAmtFC),
+                ReceiptAmount = 0,
+                CreditAmount = 0,
+                ReceiptDocEntrys = new List<ReceiptDocEntrys>(),
+
+                // 交货、退货相关
+                DeliveryTotalAmount = GetNullableValue(ordrStat?.U_Delivery_TotalAmt),
+                DeliveryTotalAmountFC = GetNullableValue(ordrStat?.U_Delivery_TotalAmtFC),
+                UCreditTotalAmt = GetNullableValue(ordrStat?.U_Credit_TotalAmt),
+                UCreditTotalAmtFC = GetNullableValue(ordrStat?.U_Credit_TotalAmtFC),
+
+                // 应收余额计算
+                ReceiptBalance = CalculateReceiptBalance(data, ordrStat),
+                ReceiptBalanceFC = CalculateReceiptBalanceFC(data, ordrStat),
+
+                Accepted = ordrStat?.U_Accepted,
+                BillTotalAmt = ordrStat?.U_Bill_TotalAmt,
+
+                // 客户默认销售员信息
+                CustomerSlpCode = data.CustomerSlpCode,
+                CustomerSlpMan = data.CustomerSlpMan,
+            };
+        }
+
+        /// <summary>
+        /// 计算应收余额（本币）
+        /// </summary>
+        /// <param name="data">订单基础数据</param>
+        /// <param name="ordrStat">订单统计数据</param>
+        /// <returns>应收余额</returns>
+        private static decimal CalculateReceiptBalance(OrderBasicData data, OrdrStat ordrStat)
+        {
+            var creditAmount = GetNullableValue(ordrStat?.U_Credit_TotalAmt);
+            var receiptAmount = data.U_DocRCTAmount ?? 0;
+            var glAmount = GetNullableValue(ordrStat?.U_GLAmt);
+
+            if (data.DocStatus == "O")
+            {
+                // 订单状态为"O"：订单金额 - 贷项金额 - 收款金额 - GL金额
+                var docTotal = data.DocTotal ?? 0;
+                return docTotal - creditAmount - receiptAmount - glAmount;
+            }
+            else
+            {
+                // 其他状态：交货金额 - 贷项金额 - 收款金额 - GL金额
+                var deliveryAmount = GetNullableValue(ordrStat?.U_Delivery_TotalAmt);
+                return deliveryAmount - creditAmount - receiptAmount - glAmount;
+            }
+        }
+
+        /// <summary>
+        /// 计算应收余额（外币）
+        /// </summary>
+        /// <param name="data">订单基础数据</param>
+        /// <param name="ordrStat">订单统计数据</param>
+        /// <returns>应收余额（外币）</returns>
+        private static decimal CalculateReceiptBalanceFC(OrderBasicData data, OrdrStat ordrStat)
+        {
+            var creditAmountFC = GetNullableValue(ordrStat?.U_Credit_TotalAmtFC);
+            var receiptAmountFC = GetNullableValue(ordrStat?.U_Receipt_TotalAmtFC);
+            var glAmount = GetNullableValue(ordrStat?.U_GLAmt);
+
+            if (data.DocStatus == "O")
+            {
+                // 订单状态为"O"：订单金额 - 贷项金额(退货金额) - 收款金额 - GL金额
+                var docTotalFC = data.DocTotalFC ?? 0;
+                return docTotalFC - creditAmountFC - receiptAmountFC - glAmount;
+            }
+            else
+            {
+                // 其他状态：交货金额 - 贷项金额(退货金额) - 收款金额 - GL金额
+                var deliveryAmountFC = GetNullableValue(ordrStat?.U_Delivery_TotalAmtFC);
+                return deliveryAmountFC - creditAmountFC - receiptAmountFC - glAmount;
+            }
+        }
+
+        /// <summary>
+        /// 安全获取可空值，如果为null则返回0
+        /// </summary>
+        /// <param name="value">可空的decimal值</param>
+        /// <returns>实际值或0</returns>
+        private static decimal GetNullableValue(decimal? value)
+        {
+            return value ?? 0;
+        }
