+        /// <summary>
+        /// 完整收集所有关联订单（向上找主单、向下找子单）
+        /// 优化：增量查询，返回订单关系信息供后续复用
+        /// </summary>
+        /// <param name="seedOrderIds">起始订单号集合</param>
+        /// <returns>所有关联订单号集合和订单关系信息</returns>
+        private async Task<(HashSet<int> OrderIds, Dictionary<int, string> OrderRelations)>
+            CollectAllRelatedOrdersWithInfo(List<int> seedOrderIds)
+        {
+            var allRelatedOrderIds = new HashSet<int>(seedOrderIds);
+            var orderRelationDict = new Dictionary<int, string>(); // OrderId -> RelevanceOrderNos
+
+            // 向上追溯主单（增量查询，避免全表扫描）
+            var toQuery = new Queue<int>(seedOrderIds);
+            var queried = new HashSet<int>();
+
+            while (toQuery.Count > 0)
+            {
+                var currentBatch = new List<int>();
+                while (toQuery.Count > 0)
+                {
+                    var orderId = toQuery.Dequeue();
+                    if (!queried.Contains(orderId))
+                    {
+                        currentBatch.Add(orderId);
+                    }
+                }
+
+                if (currentBatch.Count == 0) break;
+
+                // 只查询当前批次的订单（而不是全表）
+                var orderInfos = await UnitWork.Find<SaleOrderInfo>(
+                    x => currentBatch.Contains(x.OrderId) && !x.IsDeleted)
+                    .Select(x => new { x.OrderId, x.RelevanceOrderNos })
+                    .ToListAsync();
+
+                foreach (var order in orderInfos)
+                {
+                    queried.Add(order.OrderId);
+                    orderRelationDict[order.OrderId] = order.RelevanceOrderNos ?? string.Empty;
+
+                    if (!string.IsNullOrEmpty(order.RelevanceOrderNos))
+                    {
+                        var mainIds = ParseOrderIds(order.RelevanceOrderNos);
+                        foreach (var mainId in mainIds)
+                        {
+                            allRelatedOrderIds.Add(mainId);
+                            if (!queried.Contains(mainId))
+                            {
+                                toQuery.Enqueue(mainId);
+                            }
+                        }
+                    }
+                }
+            }
+
+            // 向下扩展所有层级子单（查询所有有主单的订单）
+            var subOrderInfos = await UnitWork.Find<SaleOrderInfo>(
+                x => !string.IsNullOrEmpty(x.RelevanceOrderNos) && !x.IsDeleted)
+                .Select(x => new { x.OrderId, x.RelevanceOrderNos })
+                .ToListAsync();
+
+            var mainToSubOrderMap = new Dictionary<int, List<int>>();
+            foreach (var subOrder in subOrderInfos)
+            {
+                var mainIds = ParseOrderIds(subOrder.RelevanceOrderNos);
+                if (mainIds.Count == 0)
+                {
+                    continue;
+                }
+
+                if (!orderRelationDict.ContainsKey(subOrder.OrderId))
+                {
+                    orderRelationDict[subOrder.OrderId] = subOrder.RelevanceOrderNos;
+                }
+
+                foreach (var mainId in mainIds)
+                {
+                    if (!mainToSubOrderMap.ContainsKey(mainId))
+                    {
+                        mainToSubOrderMap[mainId] = new List<int>();
+                    }
+                    mainToSubOrderMap[mainId].Add(subOrder.OrderId);
+                }
+            }
+
+            var mainQueue = new Queue<int>(allRelatedOrderIds);
+            var expandedMainIds = new HashSet<int>();
+            while (mainQueue.Count > 0)
+            {
+                var currentMainId = mainQueue.Dequeue();
+                if (!expandedMainIds.Add(currentMainId))
+                {
+                    continue;
+                }
+
+                if (!mainToSubOrderMap.TryGetValue(currentMainId, out var subOrderIds))
+                {
+                    continue;
+                }
+
+                foreach (var subOrderId in subOrderIds)
+                {
+                    if (allRelatedOrderIds.Add(subOrderId) || !expandedMainIds.Contains(subOrderId))
+                    {
+                        mainQueue.Enqueue(subOrderId);
+                    }
+                }
+            }
+
+            return (allRelatedOrderIds, orderRelationDict);
+        }
+
+        /// <summary>
+        /// 为构树补齐订单关系信息，确保补充出来的无收款订单也能参与主子单组装
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="orderRelations"></param>
+        /// <returns></returns>
+        private static IEnumerable<dynamic> BuildSaleOrderInfosForProcess(
+            List<ReceiptDtoResp> allReceipts,
+            Dictionary<int, string> orderRelations)
+        {
+            return allReceipts
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value)
+                .Distinct()
+                .Select(orderId => new
+                {
+                    OrderId = orderId,
+                    RelevanceOrderNos = orderRelations.TryGetValue(orderId, out var relevanceOrderNos)
+                        ? relevanceOrderNos
+                        : string.Empty
+                })
+                .Cast<dynamic>()
+                .ToList();
+        }
+
+        /// <summary>
+        /// 构建订单关系映射
+        /// </summary>
+        /// <param name="orderNosStr"></param>
+        /// <summary>
+        /// 解析订单号字符串
+        /// </summary>
+        private static List<int> ParseOrderIds(string orderNosStr)
+        {
+            return orderNosStr
+                .Split(',', StringSplitOptions.RemoveEmptyEntries)
+                .Select(s => int.TryParse(s.Trim(), out var id) ? id : 0)
+                .Where(id => id > 0)
+                .ToList();
+        }
+
+        /// <summary>
+        /// 处理ReLoad数据的公共逻辑
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="saleOrderInfos"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<TableData<List<ReceiptReLoadResp>>> ProcessReLoadData(
+            List<ReceiptDtoResp> allReceipts,
+            IEnumerable<dynamic> saleOrderInfos,
+            ReceiptLoadReq req)
+        {
+            var tableData = new TableData<List<ReceiptReLoadResp>>();
+            var resultList = new List<ReceiptReLoadResp>();
+            var processedOrders = new HashSet<int>();
+
+            // 准备收款数据字典
+            var receiptDict = BuildReceiptDictionary(allReceipts);
+
+            // 构建订单关系映射
+            BuildOrderRelationMapsWithOrderIds(saleOrderInfos, out var orderToMainMap, out var mainToOrderMap, out var allOrderIds);
+
+            // 识别顶级主单
+            var topLevelMainOrders = IdentifyTopLevelMainOrders(allOrderIds, orderToMainMap, receiptDict);
+
+            // 处理每个顶级主单及其所有子单
+            ProcessTopLevelOrders(topLevelMainOrders, orderToMainMap, mainToOrderMap, receiptDict, resultList, processedOrders);
+
+            // 处理不在关系表中的其他订单
+            ProcessRemainingOrders(allReceipts, processedOrders, resultList);
+
+            // 分页、排序及填充额外数据
+            return await ApplyPaginationAndFillData(resultList, req, tableData);
+        }
+
+        /// <summary>
+        /// 构建收款数据字典
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <returns></returns>
+        private static Dictionary<int, ReceiptDtoResp> BuildReceiptDictionary(List<ReceiptDtoResp> allReceipts)
+        {
+            return allReceipts
+                .Where(x => x.SaleDocEntry.HasValue)
+                .GroupBy(x => x.SaleDocEntry.Value)
+                .ToDictionary(g => g.Key, g => g.First());
+        }
+
+        /// <summary>
+        /// 构建订单关系映射（包含所有订单ID）
+        /// </summary>
+        /// <param name="saleOrderInfos"></param>
+        /// <param name="orderToMainMap"></param>
+        /// <param name="mainToOrderMap"></param>
+        /// <param name="allOrderIds"></param>
+        private static void BuildOrderRelationMapsWithOrderIds(
+            IEnumerable<dynamic> saleOrderInfos,
+            out Dictionary<int, List<int>> orderToMainMap,
+            out Dictionary<int, List<int>> mainToOrderMap,
+            out HashSet<int> allOrderIds)
+        {
+            orderToMainMap = new Dictionary<int, List<int>>(); // 子单 -> 主单列表
+            mainToOrderMap = new Dictionary<int, List<int>>(); // 主单 -> 子单列表
+            allOrderIds = new HashSet<int>();
+
+            foreach (var order in saleOrderInfos)
+            {
+                int orderId = order.OrderId;
+                string relevanceOrderNos = order.RelevanceOrderNos;
+                allOrderIds.Add(orderId);
+
+                if (string.IsNullOrEmpty(relevanceOrderNos))
+                    continue;
+
+                var mainIds = ParseOrderIds(relevanceOrderNos);
+                if (mainIds.Count == 0)
+                    continue;
+
+                orderToMainMap[orderId] = mainIds;
+
+                foreach (var mainId in mainIds)
+                {
+                    if (!mainToOrderMap.ContainsKey(mainId))
+                    {
+                        mainToOrderMap[mainId] = new List<int>();
+                    }
+                    mainToOrderMap[mainId].Add(orderId);
+                }
+            }
+        }
+
+        /// <summary>
+        /// 识别顶级主单：没有主单或主单不在当前数据中
+        /// </summary>
+        /// <param name="allOrderIds"></param>
+        /// <param name="orderToMainMap"></param>
+        /// <param name="receiptDict"></param>
+        /// <returns></returns>
+        private static HashSet<int> IdentifyTopLevelMainOrders(
+            HashSet<int> allOrderIds,
+            Dictionary<int, List<int>> orderToMainMap,
+            Dictionary<int, ReceiptDtoResp> receiptDict)
+        {
+            var topLevelMainOrders = new HashSet<int>();
+
+            foreach (var orderId in allOrderIds)
+            {
+                if (!orderToMainMap.ContainsKey(orderId))
+                {
+                    // 没有RelevanceOrderNos，是真正的主单
+                    topLevelMainOrders.Add(orderId);
+                }
+                else
+                {
+                    // 有主单，但主单不在当前数据中，视为顶级
+                    var hasMainInData = orderToMainMap[orderId].Any(mainId => receiptDict.ContainsKey(mainId));
+                    if (!hasMainInData)
+                    {
+                        topLevelMainOrders.Add(orderId);
+                    }
+                }
+            }
+
+            return topLevelMainOrders;
+        }
+
+        /// <summary>
+        /// 处理每个顶级主单及其所有子单
+        /// </summary>
+        /// <param name="topLevelMainOrders"></param>
+        /// <param name="orderToMainMap"></param>
+        /// <param name="mainToOrderMap"></param>
+        /// <param name="receiptDict"></param>
+        /// <param name="resultList"></param>
+        /// <param name="processedOrders"></param>
+        private static void ProcessTopLevelOrders(
+            HashSet<int> topLevelMainOrders,
+            Dictionary<int, List<int>> orderToMainMap,
+            Dictionary<int, List<int>> mainToOrderMap,
+            Dictionary<int, ReceiptDtoResp> receiptDict,
+            List<ReceiptReLoadResp> resultList,
+            HashSet<int> processedOrders)
+        {
+            foreach (var topOrderId in topLevelMainOrders)
+            {
+                if (!receiptDict.ContainsKey(topOrderId) || processedOrders.Contains(topOrderId))
+                    continue;
+
+                var topReceipt = receiptDict[topOrderId];
+                var topResp = ConvertToReLoadResp(topReceipt, !orderToMainMap.ContainsKey(topOrderId));
+
+                // 递归收集所有子单
+                var allSubReceipts = CollectAllSubOrdersRecursive(topOrderId, mainToOrderMap, receiptDict, processedOrders);
+
+                // 只有存在关联单时才填充SubOrders
+                if (allSubReceipts.Count > 0)
+                {
+                    topResp.SubOrders.Add(CloneReceiptDtoResp(topReceipt));
+                    topResp.SubOrders.AddRange(allSubReceipts);
+                    AggregateSubOrdersData(topResp);
+                }
+
+                resultList.Add(topResp);
+                processedOrders.Add(topOrderId);
+            }
+        }
+
+        /// <summary>
+        /// 递归收集所有子单（包括孙单）
+        /// 优化：即使子单没有收款记录，也要收集（主单有收款时）
+        /// </summary>
+        /// <param name="parentOrderId">父订单ID</param>
+        /// <param name="mainToOrderMap">主单到子单的映射</param>
+        /// <param name="receiptDict">收款数据字典</param>
+        /// <param name="processedOrders">已处理订单集合</param>
+        /// <returns>所有子单的收款数据列表</returns>
+        private static List<ReceiptDtoResp> CollectAllSubOrdersRecursive(
+            int parentOrderId,
+            Dictionary<int, List<int>> mainToOrderMap,
+            Dictionary<int, ReceiptDtoResp> receiptDict,
+            HashSet<int> processedOrders)
+        {
+            var result = new List<ReceiptDtoResp>();
+
+            if (mainToOrderMap.TryGetValue(parentOrderId, out var subOrderIds))
+            {
+                foreach (var subOrderId in subOrderIds)
+                {
+                    if (processedOrders.Contains(subOrderId))
+                        continue;
+
+                    // 优化：即使子单没有收款记录，也要收集
+                    // 如果在receiptDict中存在，直接使用
+                    // 如果不存在，说明没有收款记录，需要构建虚拟记录（在外层已经补充）
+                    if (receiptDict.TryGetValue(subOrderId, out var subReceipt))
+                    {
+                        result.Add(CloneReceiptDtoResp(subReceipt));
+                        processedOrders.Add(subOrderId);
+
+                        // 递归收集孙单
+                        var grandChildren = CollectAllSubOrdersRecursive(subOrderId, mainToOrderMap, receiptDict, processedOrders);
+                        result.AddRange(grandChildren);
+                    }
+                }
+            }
+
+            return result;
+        }
+        /// <summary>
+        /// 处理不在关系表中的其他订单
+        /// </summary>
+        /// <param name="allReceipts"></param>
+        /// <param name="processedOrders"></param>
+        /// <param name="resultList"></param>
+        private static void ProcessRemainingOrders(
+            List<ReceiptDtoResp> allReceipts,
+            HashSet<int> processedOrders,
+            List<ReceiptReLoadResp> resultList)
+        {
+            // 处理有DocEntry但未处理的订单
+            foreach (var receipt in allReceipts.Where(x => x.SaleDocEntry.HasValue))
+            {
+                var orderId = receipt.SaleDocEntry.Value;
+                // 如果未处理过，且结果列表中还没有它
+                if (!processedOrders.Contains(orderId) && !resultList.Any(r => r.SaleDocEntry == orderId))
+                {
+                    var resp = ConvertToReLoadResp(receipt, true);
+                    // 独立订单没有关联单，不需要把自己放入SubOrders
+                    resultList.Add(resp);
+                }
+            }
+
+            // 处理没有SaleDocEntry的收款数据
+            foreach (var receipt in allReceipts.Where(x => !x.SaleDocEntry.HasValue))
+            {
+                var resp = ConvertToReLoadResp(receipt, true);
+                //  没有SaleDocEntry的收款数据没有关联单，不需要把自己放入SubOrders
+                resultList.Add(resp);
+            }
+        }
+
+        /// <summary>
+        /// 分页、排序及填充额外数据
+        /// </summary>
+        /// <param name="resultList"></param>
+        /// <param name="req"></param>
+        /// <param name="tableData"></param>
+        /// <returns></returns>
+        private async Task<TableData<List<ReceiptReLoadResp>>> ApplyPaginationAndFillData(
+            List<ReceiptReLoadResp> resultList,
+            ReceiptLoadReq req,
+            TableData<List<ReceiptReLoadResp>> tableData)
+        {
+            // 排序前预处理ReceiptBalance（处理清账状态）
+            await PreProcessReceiptBalanceForSorting(resultList);
+
+            // 动态排序
+            resultList = ApplySorting(resultList, req.SortName, req.SortOrder);
+
+            // 分页
+            tableData.Count = resultList.Count;
+            tableData.Data = resultList.Skip((req.page - 1) * req.limit).Take(req.limit).ToList();
+
+            // 分页后补充额外数据
+            var dataForFill = new List<ReceiptDtoResp>();
+            foreach (var item in tableData.Data)
+            {
+                dataForFill.Add(item);
+                if (item.SubOrders != null)
+                {
+                    dataForFill.AddRange(item.SubOrders);
+                }
+            }
+
+            await FillExtraData(dataForFill, req.RefundStatus);
+
+            return tableData;
+        }
+
+        /// <summary>
+        /// 排序前预处理ReceiptBalance
+        /// 将已清账订单的应收余额设为0，确保排序结果正确
+        /// </summary>
+        /// <param name="resultList"></param>
+        /// <returns></returns>
+        private async Task PreProcessReceiptBalanceForSorting(List<ReceiptReLoadResp> resultList)
+        {
+            if (resultList == null || resultList.Count == 0) return;
+
+            var parentIds = resultList
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value);
+
+            var subIds = resultList
+                .Where(x => x.SubOrders != null)
+                .SelectMany(x => x.SubOrders)
+                .Where(x => x.SaleDocEntry.HasValue)
+                .Select(x => x.SaleDocEntry.Value);
+
+            // 合并并去重
+            var allSaleDocEntries = new HashSet<int>(parentIds.Concat(subIds));
+
+            if (allSaleDocEntries.Count == 0) return;
+
+            var clearedOrders = await UnitWork.Find<FinanceClearReconJournal>(x =>
+                    x.BaseDocEntry.HasValue &&
+                    allSaleDocEntries.Contains(x.BaseDocEntry.Value) &&
+                    x.Status == ClearReconcStatus.审批通过)
+                .Select(x => x.BaseDocEntry.Value)
+                .Distinct()
+                .ToListAsync();
+
+            if (clearedOrders.Count == 0) return;
+
+            var clearedOrderSet = new HashSet<int>(clearedOrders);
+
+            foreach (var item in resultList)
+            {
+                //  存在子单 -> 处理子单并重新汇总主单
+                if (item.SubOrders?.Count > 0)
+                {
+                    foreach (var sub in item.SubOrders)
+                    {
+                        // 如果子单 ID 存在且在清账集合中
+                        if (sub.SaleDocEntry.HasValue && clearedOrderSet.Contains(sub.SaleDocEntry.Value))
+                        {
+                            // AI Modified: 同时清零本币和外币应收余额
+                            sub.ReceiptBalance = 0;
+                            sub.ReceiptBalanceFC = 0;
+                        }
+                    }
+
+                    // 重新计算主单余额 (保持原逻辑：主单余额 = 子单余额之和)
+                    // AI Modified: 同时汇总本币和外币
+                    item.ReceiptBalance = item.SubOrders.Sum(x => x.ReceiptBalance);
+                    item.ReceiptBalanceFC = item.SubOrders.Sum(x => x.ReceiptBalanceFC);
+                }
+                // 无子单的主单 -> 直接判断主单 ID
+                else if (item.SaleDocEntry.HasValue && clearedOrderSet.Contains(item.SaleDocEntry.Value))
+                {
+                    // AI Modified: 同时清零本币和外币应收余额
+                    item.ReceiptBalance = 0;
+                    item.ReceiptBalanceFC = 0;
+                }
+            }
+        }
+
+        /// <summary>
+        /// 根据排序字段和排序方式对结果列表进行排序
+        /// 当主排序字段值相同时，按SaleDocEntry作为次要排序条件确保排序稳定
+        /// </summary>
+        /// <param name="resultList"></param>
+        /// <param name="sortName">排序字段名称（忽略大小写）</param>
+        /// <param name="sortOrder">排序方式（asc/desc）</param>
+        /// <returns></returns>
+        private static List<ReceiptReLoadResp> ApplySorting(List<ReceiptReLoadResp> resultList, string sortName, string sortOrder)
+        {
+            // 默认排序字段
+            if (string.IsNullOrEmpty(sortName))
+            {
+                sortName = "ReceiptBalance";
+            }
+            // 默认降序
+            bool isAsc = sortOrder?.ToLower() == "asc";
+
+            // 使用反射获取属性进行排序（忽略大小写）
+            var propertyInfo = typeof(ReceiptReLoadResp).GetProperty(sortName, System.Reflection.BindingFlags.IgnoreCase | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
+            if (propertyInfo == null)
+            {
+                // 属性不存在时使用默认排序
+                return resultList.OrderByDescending(x => x.ReceiptBalance).ThenByDescending(x => x.SaleDocEntry).ToList();
+            }
+
+            if (isAsc)
+            {
+                return resultList
+                    .OrderBy(r => propertyInfo.GetValue(r, null))
+                    .ThenBy(r => r.SaleDocEntry)
+                    .ToList();
+            }
+            else
+            {
+                return resultList
+                    .OrderByDescending(r => propertyInfo.GetValue(r, null))
+                    .ThenByDescending(r => r.SaleDocEntry)
+                    .ToList();
+            }
+        }
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="resultList"></param>
+        /// <param name="sortName"></param>
+        /// <param name="sortOrder"></param>
+        /// <returns></returns>
+
+        private static List<ReceiptDtoResp> ApplySorting(List<ReceiptDtoResp> resultList, string sortName, string sortOrder)
+        {
+            // 默认排序字段
+            if (string.IsNullOrEmpty(sortName))
+            {
+                sortName = "ReceiptBalance";
+            }
+            // 默认降序
+            bool isAsc = sortOrder?.ToLower() == "asc";
+
+            // 使用反射获取属性进行排序（忽略大小写）
+            var propertyInfo = typeof(ReceiptDtoResp).GetProperty(sortName, System.Reflection.BindingFlags.IgnoreCase | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
+            if (propertyInfo == null)
+            {
+                // 属性不存在时使用默认排序
