+        private async Task FilterIndicators(ReceiptLoadReq req, List<ModuleElement> moduleElements)
+        {
+            var loginContext = _auth.GetCurrentUser();
+            
+            //有权限查看的标识（除了ALL之外的）
+            var customQryCategory = await UnitWork.Find<Category>(x => x.TypeId == FinanceConsts.FICO_Custom_Query_Filter).ToListAsync();
+            var haveCustomQueryRight = customQryCategory.Select(x => x.DtCode).Intersect(moduleElements.Select(x => x.DomId)).Distinct().ToList();
+            if (haveCustomQueryRight.Count > 0)
+            {
+                var customQryIndicators = customQryCategory.Where(x => haveCustomQueryRight.Contains(x.DtCode)).Select(x => x.DtValue).ToList();
+                if (req.IndicatorList == null || req.IndicatorList.Count == 0)
+                {
+                    //处理选择无标识时的参数格式
+                    req.IndicatorList = customQryIndicators;
+                }
+                else if (req.IndicatorList.Except(customQryIndicators).Any()) // 校验存在非法标识
+                {
+                    // 获取非法标识列表
+                    var invalidItems = req.IndicatorList.Except(customQryIndicators).ToList();
+                    var idcinfo = await UnitWork.Find<crm_oidc>(x => x.sbo_id == Define.SBO_ID).Where(x => invalidItems.Contains(x.Code)).Select(x => x.Name).ToListAsync();
+                    throw new InvalidOperationException($"无查看{string.Join("，", idcinfo)}标识的权限");
+                }
+                req.IndicatorList = req.IndicatorList.ConvertAll(i => i == Define.Non_IndicatorCode ? "N" : i);
+                return;
+            }
+
+            // 获取登录标识权限
+            List<string> indicators;
+            if (loginContext.LoginIndicates.Exists(x => x.IndicateCode == Define.All_IndicatorCode))
+            {
+                var allIndicators = await UnitWork.Find<Category>(x => x.TypeId == Define.CompanyEntity).Select(x => x.DtCode).ToListAsync();
+                indicators = allIndicators.Where(x => x != Define.All_IndicatorCode).ToList();
+            }
+            else
+            {
+                indicators = loginContext.LoginIndicates.Select(x => x.IndicateCode).ToList();
+            }
+            indicators = indicators.ConvertAll(i => i == Define.Non_IndicatorCode ? "N" : i);
+
+            // 请求参数带有IndicatorList参数
+            if (req.IndicatorList != null && req.IndicatorList.Count > 0)
+            {
+                // 请求带有IndicatorList参数时，需要判断权限
+                req.IndicatorList = req.IndicatorList.Intersect(indicators).ToList();
+                if (!req.IndicatorList.Any())
+                {
+                    throw new InvalidOperationException("无查看所选公司主体标识的权限");
+                }
+            }
+            else// 请求参数没有IndicatorList参数
+            {
+                var loginInfo = _auth.GetLoginInfo();
+                if (loginInfo.IndicateName == Define.All_Indicator)// 登录时公司主体选择ALL，查询用户有权限的所有单据
+                {
+                    // IDC接口标识多选参数查询
+                    req.IndicatorList = indicators;
+                }
+                else// 登录选择了不是ALL的具体标识，默认筛选登录选择的标识
+                {
+                    req.Indicator = loginInfo.IndicateCode == Define.Non_IndicatorCode ? "N" : loginInfo.IndicateCode;
+                }
+            }
+        }
