+        private async Task SearchSlpCodes(ReceiptLoadReq req)
+        {
+            // 关键字检索出erp3用户id
+            List<int?> erp3Ids = default;
+            var userName = req.SearchText.Split("-").Count() > 1 ? req.SearchText.Split("-")[1] : req.SearchText;
+            var org = req.SearchText.Split('-').Count() > 1 ? req.SearchText.Split('-')[0] : string.Empty;
+            //如果申请人是带部门，则是查该部门下的申请人
+            if (!string.IsNullOrEmpty(org))
+            {
+                erp3Ids = await (from a in UnitWork.Find<User>(null)
+                                 join b in UnitWork.Find<Relevance>(r => r.Key == Define.USERORG) on a.Id equals b.FirstId
+                                 join c in UnitWork.Find<OpenAuth.Repository.Domain.Org>(null) on b.SecondId equals c.Id
+                                 where a.Name.Contains(userName) && c.Name.Equals(org)
+                                 select a.User_Id).Distinct().ToListAsync();
+            }
+            //输入的可能是部门，也可能是申请人
+            else
+            {
+                erp3Ids = await (from a in UnitWork.Find<User>(null)
+                                 join b in UnitWork.Find<Relevance>(r => r.Key == Define.USERORG) on a.Id equals b.FirstId
+                                 join c in UnitWork.Find<OpenAuth.Repository.Domain.Org>(null) on b.SecondId equals c.Id
+                                 where a.Name.Contains(userName) || c.Name.Equals(userName)
+                                 select a.User_Id).Distinct().ToListAsync();
+            }
+            // 查询sap用户id
+            var slpCodes = new List<string>();
+            var searchIds = erp3Ids.Where(erp3Id => erp3Id.HasValue && erp3Id.Value > 0).Select(erp3Id => (uint)erp3Id.Value).ToList();
+            if (searchIds.Count > 0)
