+                slpCodes = await UnitWork.Find<sbo_user>(su => su.sbo_id == 1 && searchIds.Contains(su.user_id)).Select(su => su.sale_id.ToString()).ToListAsync();
+            }
+            // 原先无人员筛选条件，则加上筛选条件；已有筛选条件则取交集
+            if (req.SlpCodes != null && req.SlpCodes.Count > 0)
+            {
+                req.SlpCodes = req.SlpCodes.Intersect(slpCodes).ToList();
+            }
+            else
+            {
+                req.SlpCodes = slpCodes;
+            }
