+        /// <summary>
+        /// 根据客户行业、客户类型和客户区域筛选收款列表
+        /// </summary>
+        /// <param name="result">收款列表</param>
+        /// <param name="req">请求参数</param>
+        /// <returns>筛选后的收款列表</returns>
+        private async Task<List<ReceiptDtoResp>> FilterByCompSectorAndCardType(List<ReceiptDtoResp> result, ReceiptLoadReq req)
+        {
+            // 如果没有筛选条件，直接返回原列表
+            if ((req.CompSectorFilter == null || req.CompSectorFilter.Count == 0) && 
+                (req.CardType == null || req.CardType.Count == 0) &&
+                string.IsNullOrEmpty(req.BelongArea))
+            {
+                return result;
+            }
+
+            // 构建 CustomerMain 查询条件
+            var predicate = PredicateBuilder.True<CustomerMain>();
+            predicate = PredicateBuilder.And(predicate, c => c.CardCode != null);
+
+            // 客户类型筛选
+            if (req.CardType != null && req.CardType.Count > 0)
+            {
+                // 清理CardType字符串，去除[]括号
+                var cleanedCardTypes = req.CardType
+                    .Select(x => x.Replace("[", "").Replace("]", ""))
+                    .ToList();
+                
+                // 构建第一个客户类型条件
+                Expression<Func<CustomerMain, bool>> cardTypePredicate = c => c.U_CardTypeStr.Contains(cleanedCardTypes[0]);
+                
+                // 添加其余客户类型的OR条件
+                for (int i = 1; i < cleanedCardTypes.Count; i++)
+                {
+                    var currentCt = cleanedCardTypes[i];
+                    cardTypePredicate = PredicateBuilder.CombineExpressionsWithOr(cardTypePredicate, c => c.U_CardTypeStr.Contains(currentCt));
+                }
+                
+                predicate = PredicateBuilder.And(predicate, cardTypePredicate);
+            }
+
+            // 客户行业筛选
+            var clientComspectorPattern = new Regex(@"^\[.*\]$", RegexOptions.Compiled);
+            var func = req.CompSectorFilter?.Count > 0
+                ? PredicateBuilder.False<FinanceAddOnInfoApp.CardCodeCompSector>()
+                : PredicateBuilder.True<FinanceAddOnInfoApp.CardCodeCompSector>();  // 默认返回 true，即不过滤
+
+            if (req.CompSectorFilter != null && req.CompSectorFilter.Count > 0)
+            {
+                foreach (var filter in req.CompSectorFilter)
+                {
+                    var currentFilter = filter;
+                    func = PredicateBuilder.Or(func, x => !string.IsNullOrEmpty(x.U_CompSector)
+                            && (clientComspectorPattern.Match(x.U_CompSector).Success && currentFilter.All(f =>
+                                    x.U_CompSector.Contains(f.ToString()))));
+                }
+            }
+
+            // 调用 FinanceAddOnInfoApp 获取符合条件的客户代码
+            var getCardCodes = await _financeAddOnInfoApp.FiltrateCustomerMainToGetCardCode(predicate, func.Compile());
+            
+            // 客户区域筛选
+            if (!string.IsNullOrEmpty(req.BelongArea))
+            {
+                var areaFilteredCardCodes = await FilterByBelongArea(req.BelongArea);
+                // 取交集：同时满足行业/类型和区域条件
+                getCardCodes = getCardCodes.Intersect(areaFilteredCardCodes).ToList();
+            }
+            
+            // 根据客户代码筛选收款列表
+            return result.Where(x => getCardCodes.Contains(x.CardCode)).ToList();
+        }
+
+        /// <summary>
+        /// 根据客户区域筛选，返回符合条件的客户代码列表
+        /// </summary>
+        /// <param name="belongArea">区域代码（多个用逗号分隔）</param>
+        /// <returns>符合条件的客户代码列表</returns>
+        private async Task<List<string>> FilterByBelongArea(string belongArea)
+        {
+            // 解析区域代码
+            var addressLst = belongArea.Trim().Split(',');
+            var queryabroadArea = new List<string>();
+            var querychinaArea = new List<string>();
+            var chinaAreaCodeNew = AreaCode.GetChinaAreaCodeNew();
+            
+            foreach (var item in addressLst)
+            {
+                // 获取海外国家列表
+                var abroadCodes = CustomerAreaConfigApp.GetContinentCountryByCode(item);
+                // 获取国内省份列表
+                chinaAreaCodeNew.TryGetValue(item, out List<string> chinaCodes);
+                chinaCodes = chinaCodes ?? new List<string>();
+                queryabroadArea.AddRange(abroadCodes.ToList());
+                querychinaArea.AddRange(chinaCodes.ToList());
+            }
+            
+            // 查询国家和省份代码
+            var queryabroad = await UnitWork.Find<crm_ocry>(t => queryabroadArea.Contains(t.Name))
+                .Select(t => t.Code).ToListAsync();
+            var queryChina = await UnitWork.Find<crm_ocst>(t => querychinaArea.Contains(t.Name))
+                .Select(t => t.Code).ToListAsync();
+            
+            // 构建查询条件
+            var conditions = new List<Expression<Func<CustomerAddress, bool>>>();
+            
+            // 海外国家条件
+            if (queryabroad.Any())
+            {
+                conditions.Add(ca => queryabroad.Contains(ca.Country));
+            }
+            
+            // 国内省份条件
+            if (queryChina.Any())
+            {
+                conditions.Add(ca => queryChina.Contains(ca.State));
+            }
+            
+            // 如果没有任何条件，返回空列表
+            if (!conditions.Any())
+            {
+                return new List<string>();
+            }
+            
+            // 组合条件（OR关系）
+            var combinedPredicate = conditions[0];
+            for (int i = 1; i < conditions.Count; i++)
+            {
+                combinedPredicate = PredicateBuilder.CombineExpressionsWithOr(combinedPredicate, conditions[i]);
+            }
