+        /// <summary>
+        /// 计算并更新收款进度
+        /// </summary>
+        /// <param name="item"></param>
+        private static void UpdateReceiptProgress(ReceiptDtoResp item)
+        {
+            
+            //进度条：
+            //	订单未清：
+            //		收款金额 /（订单金额 - 退货金额）
+            //	订单已清：
+            //      收款金额 / (交货金额 - 退货金额）
+            if (item.DocStatus == "O")
+            {
+                if (item.DocCur == "RMB")
+                {
+                    var dueAmount = (item.OrderAmount ?? 0) - (item.UCreditTotalAmt ?? 0);
+                    item.ReceiptProgress = dueAmount == 0 ? 1 : ((item.ReceiptTotalAmount ?? 0) / dueAmount);
+                }
+                else
+                {
+                    var dueAmountFC = (item.OrderAmountFC ?? 0) - (item.UCreditTotalAmtFC ?? 0);
+                    item.ReceiptProgress = dueAmountFC == 0 ? 1 : ((item.ReceiptTotalAmountFC ?? 0) / dueAmountFC);
+                }
+            }
+            else if (item.DocStatus == "C")
+            {
+                if (item.DocCur == "RMB")
+                {
+                    var dueAmount = (item.DeliveryTotalAmount ?? 0) - (item.UCreditTotalAmt ?? 0);
+                    item.ReceiptProgress = dueAmount == 0 ? 1 : ((item.ReceiptTotalAmount ?? 0) / dueAmount);
+                }
+                else
+                {
+                    var dueAmountFC = (item.DeliveryTotalAmountFC ?? 0) - (item.UCreditTotalAmtFC ?? 0);
+                    item.ReceiptProgress = dueAmountFC == 0 ? 1 : ((item.ReceiptTotalAmountFC ?? 0) / dueAmountFC);
+                }
+            }
+        }
