+        public async Task<TableData<ReceiptRelatedDocResp>> GetRelatedDocs(RecepitGetRelatedDocsReq req)
+        {
+            #region 销售订单查询处理
+            if (!req.DocEntryString.IsNullOrWhiteSpace())
+            {
