+
+            // 对账的银行流水
+            BankWater water = null;
+            // 流水未入账金额
+            decimal? reconAmt = null;
+            // 默认借方科目
+            GetAcctResp acct = null;
+            ReceiptBaseInfo baseInfo = null;
+
+            #region 有关联流水时，获取默认基本信息
+            if (req.Id != null && req.Id.Count > 0)
+            {
+                if (req.Id.Count > 1)
+                {
+                    throw new InvalidOperationException("收款对账的流水，不支持多选");
+                }
+                var waterId = req.Id[0];
+                water = await UnitWork.FindSingleAsync<BankWater>(x => waterId == x.Water_id);
+                if (water == null)
+                {
+                    throw new InvalidOperationException($"未匹配到id为{waterId}的流水");
+                }
+                reconAmt = water.Amount - water.InAccountAmount;
+
+                var accts = await GetAcctList(water.DealDate, water.LedgerAccount);
