+                    DocDate = water.DealDate,
+                };
+            }
+            #endregion
+
+            var relatedDoc = new List<ReceiptRelatedDoc>();
+            // 销售订单
+            relatedDoc.AddRange(await GetSaleOrders(req, reconAmt, acct));
+            // 保证金
+            relatedDoc.AddRange(await GetBidBonds(req, reconAmt, acct));
+            // 借款
