+                    Remark = string.Empty,
+                    Details = new List<JournalDetailResp>
+                    {
+                        new JournalDetailResp()
+                        {
+                            Code = acct?.AcctCode,
+                            Name = acct?.AcctName,
+                            DocEntry = -1,
+                            CreditAmt = 0,
+                            DebitAmt = reconAmt ?? x.SaleOrderAmount - x.ReceiptAmount,
+                            IsCredit = false,
+                            Currency = x.Currency,
+                            Checked = true,
+                        },
+                        new JournalDetailResp()
+                        {
+                            Code = x.CardCode,
+                            Name = x.CardName,
+                            DocEntry = -1,
+                            CreditAmt = reconAmt ?? x.SaleOrderAmount - x.ReceiptAmount,
+                            DebitAmt = 0,
+                            IsCredit = true,
+                            Currency = x.Currency,
+                            Checked = true,
+                        }
