+                item.SaleManIsLeave = userLeaves.FirstOrDefault(x => x.UserId == item.SaleManId)?.IsLeave ?? false;
+            }
+
+            // 获取移交客户的订单
+            var docEntryList = result.Select(r => r.DocEntry).Distinct().ToList();
+            var handCustomerDocEntrys = await UnitWork.Find<SaleOrderPlugin>(x => x.HandCustomer == HandCustomerEnums.Hand && docEntryList.Contains(x.DocEntry)).Select(x => x.DocEntry).ToListAsync();
+            result.Where(x => handCustomerDocEntrys.Contains(x.DocEntry))
+                .ToList()
+                .ForEach(x => x.IsMigratedCustomer = true);
+
+            // 离职售后的单，更改业务员为售后主管
+            await _financeCommonApp.ProcessAfterSalesOrdersWithSupervisorAsync(new ProcessAfterSalesOrdersParams<ReceiptRelatedDoc>
+            {
