+        /// <summary>
+        /// 验证更新收款请求的业务规则
+        /// </summary>
+        /// <param name="req"> </param>
+        /// <param name="orctInfo"> </param>
+        /// <returns></returns>
+        private async Task ValidateUpdateReceiptRequest(UpdateReceiptReq req, ORCT orctInfo)
+        {
+            var errorMessages = new List<string>();
+
+            // 收款单已结算（关联了提成结算单），不允许修改销售订单
+            if (req.SaleDocEntry.HasValue && orctInfo.U_BonusOrderNo.HasValue)
+            {
+                var isChangingSaleOrder = orctInfo.U_BonusOrderNo != req.SaleDocEntry;
+                if (isChangingSaleOrder)
+                {
+                    errorMessages.Add($"收款单已结算到提成结算单 {orctInfo.U_BonusOrderNo}，不允许修改销售订单");
+                }
+            }
+
+            // 验证销售订单存在性和业务伙伴编码
+            if (req.SaleDocEntry.HasValue)
+            {
+                var saleOrder = await UnitWork.Find<ORDR>(x => x.DocEntry == req.SaleDocEntry.Value).FirstOrDefaultAsync();
+                if (saleOrder == null)
+                {
+                    errorMessages.Add($"销售订单 {req.SaleDocEntry} 不存在");
+                }
+                else
+                { 
+                    if (orctInfo.CardCode != saleOrder.CardCode)
+                    {
+                        errorMessages.Add($"不能修改业务伙伴编码，原收款单业务伙伴编码：{orctInfo.CardCode}，新销售订单业务伙伴编码：{saleOrder.CardCode}");
+                    } 
+                    if (orctInfo.CardName != saleOrder.CardName)
+                    {
+                        errorMessages.Add($"业务伙伴名称不匹配，原收款单业务伙伴名称：{orctInfo.CardName}，新销售订单业务伙伴名称：{saleOrder.CardName}");
+                    }
+
+                    //  验证标识与总账科目的配对关系
+                    await ValidateIndicatorWithLedgerAccount(saleOrder.Indicator, orctInfo, errorMessages);
+                }
+            }
+
+            if (errorMessages.Any())
+            {
+                throw new InvalidOperationException($"更新收款验证失败：{string.Join("；", errorMessages)}");
+            }
+        }
+
+        /// <summary>
+        /// 验证标识与总账科目的配对关系
+        /// </summary>
+        /// <param name="saleOrderIndicator">销售订单标识</param>
+        /// <param name="orctInfo">收款单信息</param>
+        /// <param name="errorMessages">错误信息列表</param>
+        /// <returns></returns>
+        private async Task ValidateIndicatorWithLedgerAccount(string saleOrderIndicator, ORCT orctInfo, List<string> errorMessages)
+        {
+            // 获取收款单使用的总账科目
+            string ledgerAccount = null;
+            
+            // 根据收款方式确定使用的总账科目
+            if (!string.IsNullOrEmpty(orctInfo.CashAcct) && orctInfo.CashSum > 0)
+            {
+                ledgerAccount = orctInfo.CashAcct;
+            }
+            else if (!string.IsNullOrEmpty(orctInfo.CheckAcct) && orctInfo.CheckSum > 0)
+            {
+                ledgerAccount = orctInfo.CheckAcct;
+            }
+            else if (!string.IsNullOrEmpty(orctInfo.TrsfrAcct) && orctInfo.TrsfrSum > 0)
+            {
+                ledgerAccount = orctInfo.TrsfrAcct;
+            }
+            else if (!string.IsNullOrEmpty(orctInfo.BankAcct))
+            {
+                ledgerAccount = orctInfo.BankAcct;
+            }
+
+            if (string.IsNullOrEmpty(ledgerAccount))
+            {
+                errorMessages.Add("无法确定收款单使用的总账科目");
+                return;
+            }
+
+            // 查询总账科目配置，验证标识是否匹配
+            var ledgerAcctConfig = await UnitWork.Find<FinanceLedgeracct>(x => x.AccountCode == ledgerAccount).FirstOrDefaultAsync();
+            if (ledgerAcctConfig == null)
+            {
+                errorMessages.Add($"总账科目 {ledgerAccount} 未在系统中配置");
+                return;
+            }
+
+            // 验证标识是否匹配
+            if (!string.IsNullOrEmpty(ledgerAcctConfig.Indicator) && 
+                !string.IsNullOrEmpty(saleOrderIndicator) && 
+                ledgerAcctConfig.Indicator != saleOrderIndicator)
+            {
+                errorMessages.Add($"销售订单标识 {saleOrderIndicator} 与总账科目 {ledgerAccount} 配置的标识 {ledgerAcctConfig.Indicator} 不匹配");
+            }
+        }
