+        /// <summary>
+        /// 每日更新汇率
+        /// </summary>
+        /// <returns></returns>
+        public async Task UpdateCurrencyByDailyJob()
+        {
+            var udpateDate = DateTime.Now;
+            var today = udpateDate.Date;
+            var dailyRows = await GetCurrencyByDate(DateTime.Now);
+            
+            var updateRows = dailyRows.Select(x => new 
+            {
+                notUpdateYet = x.notUpdateYet,
+                currency = x.Currency,
+                rate = decimal.TryParse(x.Rate,out var parseRate) ? parseRate : 0
+            });
+            
+            while(updateRows.All(x=>x.rate == 0)) //周六日节假日是没有汇率的，要取最近工作日里有汇率的
+            {
+                //查看前一天的汇率
+                udpateDate = udpateDate -TimeSpan.FromDays(1);
+                dailyRows = await GetCurrencyByDate(udpateDate);
+                updateRows = dailyRows.Select(x => new
+                {
+                    notUpdateYet = x.notUpdateYet,
+                    currency = x.Currency,
+                    rate = decimal.TryParse(x.Rate, out var parseRate) ? parseRate : 0
+                });
+            }
+            if (updateRows.Any(x => x.notUpdateYet) && udpateDate.Date == today) //如果有还未更新的就更新
+            {
+                var updateRecords = updateRows.Where(x => x.notUpdateYet).Select(x => new CurrencyRecord
+                {
+                    currency = x.currency,
+                    rate = x.rate
+                });
+                var updateReq = new UpdateCurrencyReq
+                {
+                    dateTime = today,
+                    currencys = updateRecords.ToList()
+                };
+                
+                await UpdateCurrencyByDate(updateReq,isJob:true);
+            }
+            else if (udpateDate.Date != today)
+            {
+                var updateRecords = updateRows.Select(x => new CurrencyRecord
+                {
+                    currency = x.currency,
+                    rate = x.rate
+                });
+                var updateReq = new UpdateCurrencyReq
+                {
+                    dateTime = today,
+                    currencys = updateRecords.ToList()
+                };
+                await UpdateCurrencyByDate(updateReq, isJob: true);
+            }
+        }
+        /// <summary>
+        /// 根据时间获取当日外币汇率用于更新
+        /// </summary>
+        /// <param name="date"></param>
+        /// <returns></returns>
+        public async Task<List<GetCurrencyDailyRow>> GetCurrencyByDate(DateTime date)
+        {
+            // 1. 获取所有币种配置
+            var currencySet = await UnitWork.Find<Financecurrencyset>(null).Select(x => new CurrencySet { CurrCode = x.CurrCode, Extension = x.Extension }).ToListAsync();
+            // 2. 查询币种当天最新汇率
+            var financeOrtts = await UnitWork.Find<FinanceOrtt>(x => x.IsNew && x.RateDate == date.Date)
+                .Select(x => new DailyCurrency { Currency = x.Currency, Rate =  x.Rate })
+                .ToListAsync();
+            // 3. 合并已有汇率的币种（使用HashSet）
+            var existingCurrencies = financeOrtts.ToDictionary(x => x.Currency, x => x.Rate);
+
+            // 4. 准备结果集
+            var result = new List<GetCurrencyDailyRow>();
+            var dateStr = date.ToString(Define.DateFormat1);     
+            foreach (var currency in currencySet)
+            {
+                // 5.1 已有汇率的币种
+                if (existingCurrencies.ContainsKey(currency.CurrCode))
+                {
+                    result.Add(new GetCurrencyDailyRow
+                    {
+                        Currency = currency.CurrCode,
+                        Date = dateStr,
+                        Rate = existingCurrencies[currency.CurrCode].ToString(),
+                        notUpdateYet = false
+                    });
+                    continue;
+                }
+
+                await Task.Delay(500);
+                // 5.2 获取中国货币网数据
+                var resp = await GetChinaMoneyCurrencyData(dateStr, currency.Extension);
+                string rate = "";
+                if (resp?.Records?.Any() == true)
+                {
+                    rate = resp.Records[0].Values.FirstOrDefault() ?? "";
+
+                    // 特殊币种处理
+                    if (currency.Extension == "100JPY/CNY")
+                    {
+                        rate = decimal.Round(decimal.Parse(rate) / 100.0M, 6).ToString();
+                    }
+                    // 通用处理逻辑：判断CNY位置
+                    else if (!string.IsNullOrEmpty(rate))
+                    {
+                        var parts = currency.Extension.Split('/');
+                        if (parts.Length == 2)
+                        {
+                            // CNY在分母位置（如USD/CNY）
+                            if (parts[1].Equals("CNY", StringComparison.OrdinalIgnoreCase))
+                            {
+                                // 直接使用获取的汇率值
+                            }
+                            // CNY在分子位置（如CNY/USD）
+                            else if (parts[0].Equals("CNY", StringComparison.OrdinalIgnoreCase))
+                            {
+                                // 取倒数：1单位外币 = 1/rate CNY
+                                rate = decimal.Round(1 / decimal.Parse(rate), 6).ToString();
+                            }
+                        }
+                    }
+                }
+
+                result.Add(new GetCurrencyDailyRow
+                {
+                    Currency = currency.CurrCode,
+                    Date = dateStr,
+                    Rate = rate,
+                    notUpdateYet = true
+                });
+            }
+            return result.OrderBy(x => x.Currency).ToList();
+        }
