+        /// <summary>
+        /// 预计算无单收款的授权SlpCode（主要是离职员工的SlpCode）
+        /// 用于筛选没有关联销售订单的收款记录
+        /// </summary>
+        /// <param name="currentUserSlpCodes">当前用户的SlpCode列表(int)</param>
+        /// <param name="erp3UserId">当前用户的ERP3用户ID</param>
+        /// <returns>授权的SlpCode列表</returns>
+        private async Task<List<int>> PreComputeAuthorizedNoOrderSlpCodes(List<int> currentUserSlpCodes, int? erp3UserId)
+        {
+            var authorizedSlpCodes = new HashSet<int>();
+            
+            if (!erp3UserId.HasValue || currentUserSlpCodes == null || !currentUserSlpCodes.Any())
+            {
+                return authorizedSlpCodes.ToList();
+            }
+
+            
+            try
+            {
+
+                // 获取用户映射
+                var userMap = await _userManagerApp.GetNsapUsersAsync();
+                var currentUserId = userMap.FirstOrDefault(u => u.NsapUserId == erp3UserId.Value)?.UserID;
+                
+                if (string.IsNullOrEmpty(currentUserId))
+                {
+                    return authorizedSlpCodes.ToList();
+                }
+
+                // 查找离职和在职员工
+                var allUserIds = userMap.Select(u => u.UserID).Distinct().ToList();
+                var userLeaves = await _financeCommonApp.GetUserIsLeave(allUserIds);
+                
+                var leavedUserIds = userLeaves.Where(x => x.IsLeave).Select(x => x.UserId).ToList();
+                var activeUserIds = userLeaves.Where(x => !x.IsLeave).Select(x => x.UserId).ToList();
+                
+                var leavedErp3UserIds = userMap.Where(u => leavedUserIds.Contains(u.UserID))
+                    .Select(u => u.NsapUserId).ToList();
+                var activeErp3UserIds = userMap.Where(u => activeUserIds.Contains(u.UserID))
+                    .Select(u => u.NsapUserId).ToList();
+                
+
+                
+                // 离职员工的SlpCode
+                var leavedSlpCodesRaw = await UnitWork.Find<sbo_user>(x => 
+                    x.sbo_id == Define.SBO_ID && 
+                    leavedErp3UserIds.Contains((int)x.user_id)
+                ).Select(x => (int)x.sale_id).Distinct().ToListAsync();
+                
+                // 在职员工的SlpCode
+                var activeSlpCodes = await UnitWork.Find<sbo_user>(x => 
+                    x.sbo_id == Define.SBO_ID && 
+                    activeErp3UserIds.Contains((int)x.user_id)
+                ).Select(x => (int)x.sale_id).Distinct().ToListAsync();
+                
+                // 核心优化：从离职SlpCode中排除在职SlpCode（避免误判）
+                var leavedSlpCodes = leavedSlpCodesRaw
+                    .Where(slpCode => !activeSlpCodes.Contains(slpCode))
+                    .ToList();
+                
+
+                if (!leavedSlpCodes.Any())
+                {
+                    LogHelper.Info($"预计算无单授权SlpCode：没有离职SlpCode，返回空列表", 
+                        nameof(ReceiptApp), nameof(PreComputeAuthorizedNoOrderSlpCodes));
+                    return authorizedSlpCodes.ToList();
+                }
+
+                var noOrderReceipts = await (from orct in UnitWork.Find<ORCT>(x => x.U_XSDD == null)
+                                             join ocrd in UnitWork.Find<OCRD>(null) on orct.CardCode equals ocrd.CardCode
+                                             where leavedSlpCodes.Contains(Convert.ToInt32(orct.U_U_XSDBCode ?? "0"))
+                                             select new
+                                             {
+                                                 SlpCode = Convert.ToInt32(orct.U_U_XSDBCode ?? "0"),
+                                                 CustomerSlpCode = ocrd.SlpCode ?? 0
+                                             }).Distinct().ToListAsync();
+
+
+                // 筛选：CustomerSlpCode是当前用户的SlpCode
+                // UnionWith 会自动处理去重
+                authorizedSlpCodes.UnionWith(
+                    noOrderReceipts
+                        .Where(r => currentUserSlpCodes.Contains(r.CustomerSlpCode))
+                        .Select(r => r.SlpCode)
+                );
+
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, "预计算无单授权SlpCode失败", 
+                    nameof(ReceiptApp), nameof(PreComputeAuthorizedNoOrderSlpCodes));
+            }
+
+            return authorizedSlpCodes.ToList();
+        }
