+        /// <summary>
+        /// 部门范围筛选
+        /// </summary>
+        /// <param name="receiptList">收款列表</param>
+        /// <param name="deptIndi">部门标识（S/CS/Other）</param>
+        /// <returns></returns>
+        private List<ReceiptDtoResp> FilterDept(List<ReceiptDtoResp> receiptList, string deptIndi)
+        {
+            if (string.IsNullOrEmpty(deptIndi))
+            {
+                return receiptList;
+            }
+
+            // 获取用户名与部门的映射字典
+            var orgNameDic = _userDepartMsgHelp.GetUserNameOrgDictionary();
+            foreach (var item in receiptList)
+            {
+
+                // 赋值部门，优先使用CustomerSlpMan（当前客户业务员）
+                string key = !string.IsNullOrEmpty(item.CustomerSlpMan) ? item.CustomerSlpMan : item.SaleMan;
+                if (key != null && orgNameDic.TryGetValue(key, out var org))
+                {
+                    item.DeptName = org;
+                }
+                else
+                {
+                    item.DeptName = string.Empty;
+                }
+
+            }
+
+            var deptIndiUpper = deptIndi.Trim().ToUpper();
+            if (deptIndiUpper == "S")
+            {
+                // S部门：匹配 S.+-*、R22、G0、N1* 开头的部门
+                receiptList = receiptList.Where(w => Spre_Pattern.IsMatch(w.DeptName) || R22_Pattern.IsMatch(w.DeptName) || G0_Pattern.IsMatch(w.DeptName) || N1_Pattern.IsMatch(w.DeptName)).ToList();
+            }
+            else if (deptIndiUpper == "CS")
+            {
+                // CS部门：匹配 CS[0-9]+-* 开头的部门
