+        /// <summary>
+        /// 填充客户风险状态
+        /// </summary>
+        /// <param name="dataList">数据列表</param>
+        private async Task FillCustomerRiskStatus(List<ReceiptDtoResp> dataList)
+        {
+            if (dataList == null || !dataList.Any())
+                return;
+
+            // 获取所有CardCode
+            var cardCodes = dataList.Select(x => x.CardCode).Where(c => !string.IsNullOrEmpty(c)).Distinct().ToList();
+            if (!cardCodes.Any())
+                return;
+
+            // 获取风险状态
+            var riskStatusDict = await _financeAddOnInfoApp.GetCustomerRiskStatusByCardCodesAsync(cardCodes);
+
+            // 填充风险状态
+            foreach (var item in dataList)
+            {
+                if (riskStatusDict.TryGetValue(item.CardCode, out var riskStatus))
+                {
+                    var statusList = new List<Finance.Response.CustomerRiskStatusType>();
+                    if (riskStatus.IsCancelled)
+                        statusList.Add(Finance.Response.CustomerRiskStatusType.Cancelled);
+                    if (riskStatus.IsDishonest)
+                        statusList.Add(Finance.Response.CustomerRiskStatusType.Dishonest);
+                    if (riskStatus.IsException)
+                        statusList.Add(Finance.Response.CustomerRiskStatusType.Exception);
+                    if (riskStatus.IsRevoked)
+                        statusList.Add(Finance.Response.CustomerRiskStatusType.Revoked);
+                    if (riskStatus.IsBankruptcy)
+                        statusList.Add(Finance.Response.CustomerRiskStatusType.Bankruptcy); 
+
+                    item.CustomerRiskStatus = statusList;
+                }
+            }
+        }
