+                        .Select(u => new { u.Id, u.Name, u.EntryTime })
+                        .FirstOrDefaultAsync()
+                    : null;
+                var userNameOrgDictionary = _userDepartMsgHelp.GetUserNameOrgDictionary();
+                var slpName = rawList.FirstOrDefault()?.SlpName ?? "";
+                var deptName = userNameOrgDictionary.TryGetValue(slpName, out var org) ? org : "";
+
+                decimal tenureMonths = 0;
+                if (saleUser?.EntryTime != null)
+                {
+                    var (totalMonths, _, _) = CaculateWorkYear(saleUser.EntryTime.Value);
+                    tenureMonths = totalMonths;
+                }
+
+                // 获取人员类型
+                var allSaleManIds = rawList
+                    .Select(x => userMap.FirstOrDefault(u => u.NsapUserId == (int)(erpUserIdList.FirstOrDefault(e => e.sale_id == x.CustomerSlpCode)?.user_id ?? 0))?.UserID)
+                    .Where(x => !string.IsNullOrEmpty(x))
+                    .Distinct()
+                    .ToList();
+                var userType = await _employeeApp.GetEmployeeTypeAsync(allSaleManIds);
+
+                // 获取离职状态（用于判断是否需要替换当前业务员）
+                var saleManIsLeave = false;
+                if (!string.IsNullOrEmpty(saleManId))
+                {
+                    var userLeaves = await _financeCommonApp.GetUserIsLeave(new List<string> { saleManId });
+                    saleManIsLeave = userLeaves.FirstOrDefault(x => x.UserId == saleManId)?.IsLeave ?? false;
+                }
+
+                // 组装明细数据
+                var detailList = rawList.Select(x =>
+                {
+                    var customerErp3UserId = (int)(erpUserIdList.FirstOrDefault(e => e.sale_id == x.CustomerSlpCode)?.user_id ?? 0);
+                    var customerSaleManId = userMap.FirstOrDefault(u => u.NsapUserId == customerErp3UserId)?.UserID;
+                    var customerUserType = userType.FirstOrDefault(u => u.UserId == customerSaleManId)?.UserType;
+
+                    return new SalesReceiptDetailResp
+                    {
+                        ReceiptDocEntry = x.ReceiptDocEntry,
+                        SaleDocEntry = x.SaleDocEntry,
+                        CardCode = x.CardCode,
+                        CardName = x.CardName,
+                        Indicator = x.Indicator,
+                        IndicatorName = x.IndicatorName,
+                        ReceiptAmount = x.ReceiptAmount,
+                        ReceiptAmountFC = x.ReceiptAmountFc,
+                        DocCur = x.ReceiptDocCur,
+                        DocRate = x.ReceiptDocRate,
+                        ReceiptDate = x.ReceiptDocDate,
+                        DocDate = x.ReceiptDocDate,
+                        OrderAmount = x.OrderAmount,
+                        OrderAmountFC = x.OrderAmountFc,
+                        DeliveryTotalAmount = x.DeliveryTotalAmount,
+                        DeliveryTotalAmountFC = x.DeliveryTotalAmountFc,
+                        UCreditTotalAmt = x.UCreditTotalAmt,
+                        UCreditTotalAmtFC = x.UCreditTotalAmtFc,
+                        Remarks = x.Remarks,
+                        CustomerErp3UserId = customerErp3UserId,
+                        CustomerSlpCode = x.CustomerSlpCode,
+                        CustomerSlpMan = x.CustomerSlpMan,
+                        CustomerSaleManId = customerSaleManId,
+                        CustomerUserType = customerUserType
+                    };
+                }).ToList();
+
+                // 处理 Customer 字段清理（与 LoadLocal 逻辑一致）
+                // 如果销售员未离职，清空 Customer 字段
+                if (!saleManIsLeave)
+                {
+                    foreach (var item in detailList)
+                    {
+                        item.CustomerErp3UserId = 0;
+                        item.CustomerSaleManId = "";
+                        item.CustomerSlpCode = 0;
+                        item.CustomerSlpMan = "";
+                        item.CustomerUserType = "";
+                    }
+                }
+
+                // 排序
+                if (!string.IsNullOrEmpty(req.SortName))
+                {
+                    bool isAsc = string.Equals(req.SortOrder, "asc", StringComparison.OrdinalIgnoreCase);
+                    var propertyInfo = typeof(SalesReceiptDetailResp).GetProperty(req.SortName,
+                        System.Reflection.BindingFlags.IgnoreCase | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
+                    if (propertyInfo != null)
+                    {
+                        detailList = isAsc
+                            ? detailList.OrderBy(r => propertyInfo.GetValue(r, null)).ToList()
+                            : detailList.OrderByDescending(r => propertyInfo.GetValue(r, null)).ToList();
+                    }
+                    else
+                    {
+                        detailList = detailList.OrderByDescending(x => x.ReceiptDate).ToList();
+                    }
+                }
+                else
+                {
+                    detailList = detailList.OrderByDescending(x => x.ReceiptDate).ToList();
+                }
+
+                // 分页
+                var count = detailList.Count;
+                var totalAmount = detailList.Sum(x => x.ReceiptAmount);
+                var pagedResult = detailList.Skip((req.page - 1) * req.limit).Take(req.limit).ToList();
+
+                var resp = new SalesReceiptDetailListResp
+                {
+                    SaleMan = slpName,
+                    DeptName = deptName,
+                    EntryDate = saleUser?.EntryTime,
+                    TenureMonths = tenureMonths,
+                    TotalReceiptAmount = totalAmount,
+                    Data = pagedResult,
+                    Count = count
+                };
+
+                return new Infrastructure.Response<SalesReceiptDetailListResp> { Code = 200, Message = "操作成功", Result = resp };
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, "获取销售员回款明细失败", nameof(ReceiptApp), nameof(GetSalesReceiptDetailAsync));
+                return new Infrastructure.Response<SalesReceiptDetailListResp> { Code = 500, Message = "获取销售员回款明细失败：" + ex.Message };
+            }
+        }
