+        /// <summary>
+        /// 空退空出转回款：将空退单据的回款转到空出单上
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        public async Task<TableData> TransferRefundToOut(TransferRefundToOutReq req)
+        {
+            var result = new TableData();
+
+            // 根据空退销售单号查找未取消的收款单
+            var orctList = await UnitWork.Find<ORCT>(o => o.U_XSDD == req.RefundSaleDocEntry && o.Canceled == "N")
+                .ToListAsync();
+
+            if (!orctList.Any())
+            {
+                result.Code = 500;
+                result.Message = $"未找到空退销售单{req.RefundSaleDocEntry}关联的有效收款单";
+                return result;
+            }
+
+            // 获取空出销售单的CardCode用于JrnlMemo
+            var outSaleOrder = await UnitWork.Find<ORDR>(o => o.DocEntry == req.OutSaleDocEntry).Select(o => new { o.CardCode }).FirstOrDefaultAsync();
+            if (outSaleOrder == null)
+            {
+                result.Code = 500;
+                result.Message = $"空出销售单{req.OutSaleDocEntry}不存在";
+                return result;
+            }
+
+            var errorMessages = new List<string>();
+
+            // JrnlMemo格式：收款 - "业务伙伴代码cardcode" SE-销售单号
+            var jrnlMemo = $"收款 - \"{outSaleOrder.CardCode}\" SE-{req.OutSaleDocEntry}";
+
+            foreach (var docEntry in orctList.Select(orct => orct.DocEntry))
+            {                
+                var updateReq = new UpdateReceiptReq
+                {
+                    DocNum = docEntry,
+                    SaleDocEntry = req.OutSaleDocEntry,
+                    SaleMan = req.OutSaleMan,
+                    Comments = req.OutComments,
+                    JrnlMemo = jrnlMemo
+                };
+
+                try
+                {
+                    var updateResult = await UpdateReceipt(updateReq);
+                    if (updateResult.Code != 200)
+                    {
+                        errorMessages.Add($"收款单{docEntry}更新失败：{updateResult.Message}");
+                    }
+                }
+                catch (Exception ex)
+                {
+                    errorMessages.Add($"收款单{docEntry}更新异常：{ex.Message}");
+                }
+            }
+
+            if (errorMessages.Any())
+            {
+                result.Code = 500;
+                result.Message = string.Join("；", errorMessages);
+            }
+            else
+            {
+                result.Code = 200;
+                result.Message = $"成功将{orctList.Count}笔空退回款转到空出销售单{req.OutSaleDocEntry}";
+            }
+
+            return result;
+        }
+    }
